1	// The task declaration contract (per-project-scheduling DESIGN §1) — the single
2	// source of truth for what a `tasks/<name>/task.mjs` default export must carry.
3	// Both the author-time `task-declaration-shape` check and the executor-side
4	// `validate-dispatch` validate against this one function, so the accepted shape
5	// can never drift between the two surfaces.
6	
7	import { FREQUENCIES } from './slots.mjs';
8	import { MODEL_FAMILIES } from './model-map.mjs';
9	
10	// A declared timeout is always a whole number of seconds, > 0.
11	const isPositiveInt = (n) => Number.isInteger(n) && n > 0;
12	
13	// A preprocessing command must stay inside its own task directory — no absolute
14	// path and no `..` traversal in the command string — the same containment the
15	// worker-file rule gives agent_instructions (agent-preprocessing DESIGN §2).
16	const escapesTaskDir = (cmd) => /(^|\s)\//.test(cmd) || cmd.includes('..');
17	
18	// The write ceiling a task declares (DESIGN §1, §4). A declared MAXIMUM, not a
19	// promise: `none` may never open a PR, `open-pr` may open but never merge,
20	// `merged-pr` may arm auto-merge. "No change" is always legal.
21	export const OUTCOMES = ['none', 'open-pr', 'merged-pr'];
22	
23	// The executor-session repo scope a task needs (per-project-scheduling split):
24	//   'self'  — the task touches only its own repo; a project-only executor session
25	//             is all it needs. This is the default, and almost every task's scope.
26	//   'fleet' — the task reaches across the owner's other repos (e.g. growth-promote
27	//             reads every member's local packs), so its dispatch goes to a
28	//             SEPARATE, broader-scoped executor. Isolating this to the few tasks
29	//             that truly need it keeps the fleet-wide session grant off every
30	//             ordinary project's executor. The scheduler routes a fleet task's
31	//             dispatch to the `ready-for-agent-fleet` label so a distinct executor
32	//             routine (with the owner's repos in its sources) runs it.
33	export const SESSION_SCOPES = ['self', 'fleet'];
34	
35	// The signal-collector vocabulary (DESIGN §3.3). A task collects only the union
36	// of what its due tasks declare. `fleet` is canon-only (consumers cannot declare
37	// it) — that restriction is enforced where signals are collected, not here; the
38	// shape check only asserts a declared name is a real collector.
39	export const SIGNAL_NAMES = [
40	  'commits', 'prs', 'issues', 'branches', 'release',
41	  'localPacks', 'sharedMount', 'conversationLogs', 'stamp', 'fleet',
42	];
43	
44	// Validate one task declaration. Returns an array of `{ what, fix }` problems —
45	// empty means the declaration is well-formed. Pure: no I/O, no imports of the
46	// task itself; the caller supplies the already-loaded default export.
47	export function validateTaskDeclaration(decl) {
48	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) {
49	    return [{ what: 'task.mjs does not default-export a declaration object', fix: 'export default { id, frequency, precondition_signals, agent_model, expected_outcome, agent_instructions, precondition }' }];
50	  }
51	  const problems = [];
52	  const bad = (what, fix) => problems.push({ what, fix });
53	
54	  if (typeof decl.id !== 'string' || decl.id.trim() === '') {
55	    bad('the task has no string "id"', 'give the task an "id" matching its directory name');
56	  }
57	  if (!FREQUENCIES.includes(decl.frequency)) {
58	    bad(`"frequency" ${JSON.stringify(decl.frequency)} is not a legal frequency`, `set one of: ${FREQUENCIES.join(', ')}`);
59	  }
60	  if (!Array.isArray(decl.precondition_signals) || !decl.precondition_signals.every((s) => SIGNAL_NAMES.includes(s))) {
61	    bad(`"precondition_signals" must be an array of known signal names`, `use only: ${SIGNAL_NAMES.join(', ')}`);
62	  }
63	  if (!MODEL_FAMILIES.includes(decl.agent_model)) {
64	    bad(`"agent_model" ${JSON.stringify(decl.agent_model)} is not a legal model family`, `set one of: ${MODEL_FAMILIES.join(', ')}`);
65	  }
66	  if (!OUTCOMES.includes(decl.expected_outcome)) {
67	    bad(`"expected_outcome" ${JSON.stringify(decl.expected_outcome)} is not a legal outcome ceiling`, `set one of: ${OUTCOMES.join(', ')}`);
68	  }
69	  // agent_instructions — REQUIRED for an agentic task (agent_model !== 'none'):
70	  // that's the worker file the agent reads. A `none` task runs no agent, so the
71	  // field is not applicable and is neither required nor validated when present.
72	  if (decl.agent_model !== 'none' && (typeof decl.agent_instructions !== 'string' || decl.agent_instructions.trim() === '')) {
73	    bad('an agentic task (agent_model !== "none") declares no string "agent_instructions"', 'point "agent_instructions" at the worker file beside task.mjs (e.g. "task.md")');
74	  }
75	  if (typeof decl.precondition !== 'function') {
76	    bad('"precondition" is not a function', 'export a precondition(signals, config) that returns { run, reason, context? }');
77	  }
78	
79	  // session_scope — OPTIONAL, defaults to 'self'. Only a task that reaches other
80	  // repos declares 'fleet' (routed to the fleet executor). A bad value would
81	  // silently mis-route the dispatch, so it is validated when present.
82	  if (decl.session_scope !== undefined && !SESSION_SCOPES.includes(decl.session_scope)) {
83	    bad(`"session_scope" ${JSON.stringify(decl.session_scope)} is not a legal session scope`, `omit it (defaults to "self") or set one of: ${SESSION_SCOPES.join(', ')}`);
84	  }
85	
86	  // Preprocessing (agent-preprocessing DESIGN §2) — OPTIONAL. A command the
87	  // scheduler runs as a subprocess before the agent. When present it must be a
88	  // non-empty, task-local command AND carry a positive-integer
89	  // agent_preprocessing_timeout — the hard kill that bounds the subprocess.
90	  if (decl.agent_preprocessing !== undefined) {
91	    if (typeof decl.agent_preprocessing !== 'string' || decl.agent_preprocessing.trim() === '') {
92	      bad('"agent_preprocessing" is present but not a non-empty string', 'set it to a command whose executable is a script beside task.mjs, e.g. "node prepare.mjs"');
93	    } else if (escapesTaskDir(decl.agent_preprocessing)) {
94	      bad('"agent_preprocessing" reaches outside the task directory (absolute path or "..")', 'reference a sibling script only, e.g. "node prepare.mjs"');
95	    }
96	    if (!isPositiveInt(decl.agent_preprocessing_timeout)) {
97	      bad('"agent_preprocessing" is set but "agent_preprocessing_timeout" is not a positive integer', 'add "agent_preprocessing_timeout": the seconds after which the subprocess is killed and the task fails');
98	    }
99	  }
100	
101	  // The repo Actions secrets this task needs configured (DESIGN §9). Purely
102	  // DECLARATIVE — like a pack's adoption `questions`, its job is to drive the ask
103	  // (adoption interactively, the scheduler by owner issue), not to gate anything
104	  // here. So the only shape asserted is "a list of names"; whether the repo has
105	  // actually configured them is a fact about the repo, answered where the secrets
106	  // bundle is readable, never at author time.
107	  if (decl.required_secrets !== undefined
108	      && !(Array.isArray(decl.required_secrets) && decl.required_secrets.every((s) => typeof s === 'string' && s.trim() !== ''))) {
109	    bad('"required_secrets" is not an array of secret names', 'list the repo Actions secret names this task needs, e.g. ["SOME_API_KEY"]');
110	  }
111	
112	  // Execution bound (agent-preprocessing DESIGN §2, §6) — an agentic task MUST
113	  // declare a positive-integer agent_execution_timeout. There is always a bound
114	  // on an agentic run; enforcement is best-effort (the executor surfaces the
115	  // value to the subagent). A `none` task runs no agent, so it needs none.
116	  if (MODEL_FAMILIES.includes(decl.agent_model) && decl.agent_model !== 'none' && !isPositiveInt(decl.agent_execution_timeout)) {
117	    bad('an agentic task (agent_model !== "none") declares no positive-integer "agent_execution_timeout"', 'add "agent_execution_timeout": the seconds bounding the agentic run — generous; extreme protection, not a scheduling knob');
118	  }
119	
120	  // An agentless task (agent_model: none) runs no agent, so its ONLY work is
121	  // preprocessing — a `none` task with no agent_preprocessing does nothing
122	  // (DESIGN §4, retiring the in-process inline path). Require the command.
123	  if (decl.agent_model === 'none' && decl.agent_preprocessing === undefined) {
124	    bad('an agentless task (agent_model: "none") declares no "agent_preprocessing"', 'add "agent_preprocessing" (a none task does its work in that subprocess) — or give the task an agent_model');
125	  }
126	
127	  return problems;
128	}
