1	// The scheduler entrypoint's orchestration core (per-project-scheduling DESIGN
2	// §3). The vendored hourly Action runs this: decide due slots from the run
3	// ledger, discover active tasks, collect only the signals the due tasks declare,
4	// run each precondition, and either dispatch agent work as a `ready-for-agent`
5	// issue or (for `agent_model: none`) run the worker inline.
6	//
7	// This module is the DECISION core, kept injectable so it tests with fakes: the
8	// GitHub I/O (the Actions run-ledger read for `lastSuccess`, the signal
9	// collectors, the issue search/create) is supplied by the thin CLI shell around
10	// `planRun`. The "should this run" verdict is always code here — never the
11	// shell's judgment (the same split the fleet planner uses).
12	
13	import { pathToFileURL } from 'node:url';
14	import { dueSlots, mostRecentSlot } from './slots.mjs';
15	import {
16	  planDispatch, dispatchTitle, dispatchBody, DISPATCH_PREFIX, READY_LABEL, NEEDS_HUMAN_LABEL,
17	  SCHEDULER_LABELS, readyLabelForScope, staleDispatchIssues, staleEscalationComment,
18	  rearmDispatchIssues, readyLabelOn, staleClaimedDispatchIssues, staleClaimComment,
19	  AGENT_RUNNING_LABEL,
20	} from './dispatch.mjs';
21	import { isAgentless } from './model-map.mjs';
22	import { isDormant } from '../checks/helpers/repo-context.mjs';
23	import { renderTaskRuns } from './run-record.mjs';
24	import { localSignalContext } from './signals/local.mjs';
25	import { runPreprocessing, preprocessingFailure, agentRequestPath, clearAgentRequest, agentRequested, readAgentRequest } from './preprocess.mjs';
26	
27	// The due tasks, each paired with the slot it runs under. Union the discovered
28	// tasks' frequencies, ask slots which are due (run-ledger math), then map due
29	// frequencies back to their tasks. A task whose frequency isn't due drops out.
30	export function computeDueTaskSlots(tasks, schedule, now, lastSuccess, forced = []) {
31	  const frequencies = [...new Set(tasks.map((t) => t.decl.frequency))];
32	  const due = new Map(dueSlots(frequencies, schedule, now, lastSuccess).map((d) => [d.frequency, d]));
33	  const out = [];
34	  for (const task of tasks) {
35	    const slot = due.get(task.decl.frequency);
36	    if (slot) { out.push({ task, slotId: slot.slotId, slotTime: slot.slotTime }); continue; }
37	    // A FORCED task runs under its most-recent slot even though that slot has
38	    // already been run. This gate is the reason forcing has to live here at all:
39	    // the due list is computed BEFORE any precondition, so a task whose slot has
40	    // passed is never looked at again — and a mid-day forced run is the only kind
41	    // that matters (#515). `planRun` then skips its precondition outright.
42	    if (forced.includes(task.id)) {
43	      const s = mostRecentSlot(task.decl.frequency, schedule, now);
44	      out.push({ task, slotId: s.id, slotTime: s.time, forced: true });
45	    }
46	  }
47	  return out;
48	}
49	
50	// The verdict a forced task gets INSTEAD of its precondition. The context line
51	// is generic on purpose — it names the mechanism, not the task — and it is there
52	// because a dispatch issue's Context is the agent's binding scope: a forced
53	// dispatch that carried none would read as a scope of nothing, and the agent
54	// should know it arrived by a hand-started run rather than a met condition.
55	const FORCED_VERDICT = Object.freeze({
56	  run: true,
57	  reason: 'forced by FORCE_TASKS on a manual scheduler run — its precondition was not evaluated',
58	  context: Object.freeze(['This run was forced manually (FORCE_TASKS on a workflow_dispatch); the task\'s own precondition was not evaluated, so nothing here asserts there is work to do. Do only what the task file specifies, and converge to a no-op if there is nothing.']),
59	});
60	
61	// The task ids a manual run forced, out of the opaque override bag. This is the
62	// ONE key the engine reads from that bag, and it is deliberately generic: it
63	// learns "run these task ids", never what any of them do. No task declaration
64	// mentions forcing, and no precondition is consulted for a forced task — an id
65	// matching no discovered task simply forces nothing.
66	export function forcedTaskIds(overrides = {}) {
67	  return String(overrides.FORCE_TASKS ?? '').split(',').map((s) => s.trim()).filter(Boolean);
68	}
69	
70	// The union of signal names the due tasks declare — the scheduler collects only
71	// these, so a non-daily slot never pays for daily tasks' signals (DESIGN §3.3).
72	export function signalsUnion(dueTaskSlots) {
73	  const names = new Set();
74	  for (const { task } of dueTaskSlots) for (const name of task.decl.precondition_signals) names.add(name);
75	  return [...names];
76	}
77	
78	// The signal-collection lookback: the widest due task's period plus 1h slack
79	// (DESIGN §3.3). Stateless fixed lookback — overlap is absorbed by dedupe.
80	const FREQUENCY_MS = {
81	  hourly: 3600e3, 'daily-2h': 86400e3, 'daily-1h': 86400e3, daily: 86400e3,
82	  'daily+1h': 86400e3, weekly: 7 * 86400e3, monthly: 31 * 86400e3,
83	};
84	export function windowStart(dueTaskSlots, now) {
85	  const widest = Math.max(0, ...dueTaskSlots.map(({ task }) => FREQUENCY_MS[task.decl.frequency] ?? 86400e3));
86	  return new Date(new Date(now).getTime() - widest - 3600e3).toISOString();
87	}
88	
89	// Run one task's precondition in isolation (DESIGN §3.4). A throwing
90	// precondition converges to a skip with the error recorded — it never sinks the
91	// rest of the run; the CLI escalates a thrown precondition to a workflow-failure
92	// issue separately.
93	//
94	// `exclusive` is the verdict's optional CLAIM ON THE WHOLE RUN (see planRun): a
95	// task saying "if I run, I run alone this cycle". Normalized to a boolean here,
96	// like every other field, so a precondition that omits it is simply not claiming.
97	export function runPrecondition(task, signals, packConfig) {
98	  try {
99	    const v = task.decl.precondition(signals, packConfig) ?? {};
100	    return {
101	      run: v.run === true,
102	      exclusive: v.exclusive === true,
103	      reason: v.reason ?? '',
104	      context: Array.isArray(v.context) ? v.context : [],
105	    };
106	  } catch (e) {
107	    return { run: false, exclusive: false, reason: `precondition threw: ${e.message}`, context: [], error: e.message };
108	  }
109	}
110	
111	// What a task deferred by another task's exclusive claim is told, in the run
112	// summary and the run record. Generic on purpose — it names the claimant, never
113	// what the claimant does, because the engine does not know.
114	//
115	// "Its next slot", not "the next run": due-ness is `slotTime ∈ (lastSuccess,
116	// now]` and this run succeeds, so the watermark moves past the slot that was
117	// deferred. A deferred daily task runs tomorrow, a weekly one next week. That is
118	// the price of the claim and it is stated where a person reading the run sees it.
119	export const deferredByClaim = (claimants) =>
120	  `deferred — ${claimants.join(', ')} claimed this run exclusively; this slot is spent, the task runs again at its next slot`;
121	
122	// A human-readable job-summary line per evaluated task — the observability the
123	// old plan.json gave (DESIGN §3.6).
124	export function renderSummary(evaluations) {
125	  return evaluations.map((e) => {
126	    const verb = !e.run ? 'skip' : e.deferred ? 'defer' : e.inline ? 'run-inline' : e.dispatch?.action ?? 'run';
127	    const forced = e.forced ? ' (forced)' : '';
128	    const claim = e.exclusive ? ' (exclusive)' : '';
129	    return `- ${e.pack}/${e.task} [${e.slotId}]${forced}${claim} ${verb} — ${e.deferred || e.reason || e.dispatch?.reason || ''}`.trimEnd();
130	  }).join('\n');
131	}
132	
133	// Orchestrate one scheduler run into a set of decisions — the reusable core the
134	// CLI wraps with real GitHub I/O. Injected seams:
135	//   collectSignals(names) -> signals object (the declared union, collected once)
136	//   packConfigFor(packId) -> that pack's entry config from .claudinite-checks.json
137	//   existingIssuesFor(pack, task) -> the task family's issues [{number,title,state}]
138	// Returns `{ evaluations }`: one record per due task with its precondition
139	// verdict and, when it runs, either an inline marker (agent_model: none) or a
140	// dispatch decision (planDispatch).
141	//
142	// DORMANCY IS THE FIRST GATE, ahead of the due-slot math and every task's own
143	// precondition (`config`, the repo's loaded declaration). A dormant project has
144	// said it is out of the recurring work: it is not that each task happens to have
145	// nothing to do, it is that no task is asked. Putting the gate here rather than
146	// in each precondition is the whole point — every task, canon and local, present
147	// and future, is covered by one decision nothing has to opt into, and a task
148	// never learns that dormancy exists.
149	//
150	// THE EXCLUSIVE CLAIM (owner, 2026-08-01). A precondition may return `exclusive: true`
151	// alongside `run: true`: "if I run this cycle, I run ALONE". Every other due task
152	// whose precondition also said run is deferred — no preprocessing, no dispatch
153	// issue, no inline work — and the run does that one task's work and nothing else.
154	//
155	// This exists because the hourly cron is not hourly (github-actions-scheduling:
156	// GitHub drops and delays scheduled fires freely). The daily anchors stage the
157	// nightly chain by an HOUR each — baselining at 02:00 converges the mount before
158	// the 03:00 and 04:00 tasks read it — and that staging holds only while the fires
159	// land roughly on time. A run that fires at 05:40 after three dropped fires finds
160	// all four daily slots due at once and dispatches them together, so the task whose
161	// whole job is to repair what the others run against runs BESIDE them instead of
162	// before them. The claim restores the ordering the anchors were meant to express,
163	// on exactly the runs where the anchors failed to.
164	//
165	// It is deliberately a task's decision and not the engine's: the engine learns
166	// "this verdict claims the run", never which task claims or why — the same
167	// separation `forcedTaskIds` keeps, and the reason nothing here mentions
168	// baselining. A task that never returns `exclusive` cannot be affected as a
169	// claimant, only as a deferree.
170	//
171	// A FORCED task is exempt from deferral (and cannot claim: FORCED_VERDICT carries
172	// no `exclusive`). Forcing is an operator decision already made on a hand-started
173	// run; a claim silently swallowing the task the operator asked for would make that
174	// run do nothing it was started for.
175	export async function planRun({
176	  tasks, schedule, now, lastSuccess, overrides = {}, config = {},
177	  collectSignals, packConfigFor = () => ({}), existingIssuesFor = async () => [],
178	}) {
179	  if (isDormant(config)) return { evaluations: [], dormant: true };
180	  // `overrides` arrives as a parameter rather than out of `signals` because the
181	  // due list is what decides which signals get collected — the bag has to be
182	  // known before the collection it would otherwise be part of.
183	  const dueList = computeDueTaskSlots(tasks, schedule, now, lastSuccess, forcedTaskIds(overrides));
184	  const signals = await collectSignals(signalsUnion(dueList));
185	
186	  // Pass 1 — every due task's verdict, and nothing else. Preconditions are pure
187	  // and cheap, and a claim is only knowable once they have ALL spoken, so no
188	  // issue search and no dispatch decision may happen before this pass completes.
189	  //
190	  // A FORCED task does not consult its precondition at all. "Forced" is a
191	  // decision the operator already made, so asking the task whether it agrees is
192	  // both redundant and a way for the answer to be no — and a task that could
193	  // veto a force would need to know forcing exists, which is exactly the
194	  // coupling this mechanism avoids. Nothing in a task declaration mentions
195	  // forcing; the engine owns it end to end.
196	  const verdicts = dueList.map(({ task, slotId, forced }) => ({
197	    task, slotId, forced,
198	    pre: forced ? FORCED_VERDICT : runPrecondition(task, signals, packConfigFor(task.pack)),
199	  }));
200	
201	  // The claimants: running tasks that asked for the run to themselves. More than
202	  // one is not a conflict to arbitrate — they all run and everything else defers,
203	  // which is the only reading that needs no priority order between packs.
204	  const claimants = verdicts.filter((v) => v.pre.run && v.pre.exclusive).map((v) => `${v.task.pack}/${v.task.id}`);
205	
206	  const evaluations = [];
207	  for (const { task, slotId, forced, pre } of verdicts) {
208	    const rec = {
209	      pack: task.pack, task: task.id, slotId,
210	      model: task.decl.agent_model, outcome: task.decl.expected_outcome,
211	      run: pre.run, reason: pre.reason, context: pre.context,
212	    };
213	    if (forced) rec.forced = true;
214	    if (pre.error) rec.error = pre.error;
215	    if (pre.run) {
216	      if (pre.exclusive) rec.exclusive = true;
217	      // Deferred by someone else's claim: the record keeps `run: true` (its
218	      // precondition DID say there was work) and carries no dispatch, no inline
219	      // and no preprocessing flag, so every actor downstream — the CLI action
220	      // loop, the run record, the summary — reads it as work that was wanted and
221	      // did not happen, not as a skip.
222	      if (claimants.length && !pre.exclusive && !forced) {
223	        rec.deferred = deferredByClaim(claimants);
224	        evaluations.push(rec);
225	        continue;
226	      }
227	      // A declared agent_preprocessing runs as a subprocess BEFORE any agent
228	      // (DESIGN §3) — flagged here (pure) for the summary; the CLI shell executes
229	      // it. An agentless task is preprocessing-only; an agentful one hands off to
230	      // the agent after preprocessing succeeds.
231	      if (task.decl.agent_preprocessing) rec.preprocessing = true;
232	      if (isAgentless(task.decl.agent_model)) {
233	        // agent_model: none — no agent and no dispatch issue on success. A task with
234	        // no preprocessing runs the legacy inline worker; with preprocessing it is
235	        // the subprocess above.
236	        rec.inline = true;
237	      } else {
238	        const existing = await existingIssuesFor(task.pack, task.id);
239	        // Route the dispatch to the self or fleet ready label by the task's scope
240	        // (the fleet/self executor split) — the executor routine wired to that
241	        // label runs it.
242	        const readyLabel = readyLabelForScope(task.decl.session_scope);
243	        rec.dispatch = planDispatch({ existing, pack: task.pack, task: task.id, slotId, readyLabel });
244	      }
245	    }
246	    evaluations.push(rec);
247	  }
248	  return { evaluations };
249	}
