251	// The opaque override bag a MANUAL run may carry (`workflow_dispatch` input →
252	// `CLAUDINITE_OVERRIDES`). GitHub cannot declare arbitrary named inputs, so the
253	// workflow takes ONE free-form string and this splits it into keys.
254	//
255	// Exactly one key is understood: `FORCE_TASKS` (see `forcedTaskIds`), and it is
256	// understood GENERICALLY — "run these task ids", never what any of them do. No
257	// task declaration mentions forcing and no precondition is consulted for a forced
258	// task, so the scheduler never learns what baselining is and baselining never
259	// learns that forcing exists. Anything else in the bag is parsed and ignored,
260	// which is what leaves room for a future override without a schema.
261	//
262	// `A=1,B=2`, newline-separated, or bare `A` (⇒ `'true'`). Values stay STRINGS with
263	// no truthiness coercion: a task compares against the literal it documents, so
264	// `FORCE_X=false` can never read as "the key is present, therefore on".
265	export function parseOverrides(raw) {
266	  const out = {};
267	  for (const part of String(raw ?? '').split(/[,\n]/)) {
268	    const token = part.trim();
269	    if (!token) continue;
270	    const eq = token.indexOf('=');
271	    if (eq === -1) out[token] = 'true';
272	    else out[token.slice(0, eq).trim()] = token.slice(eq + 1).trim();
273	  }
274	  return out;
275	}
