277	// The `ctx` every signal collector reads (DESIGN §3.3) — the already-resolved
278	// facts a collector may not go and fetch for itself, built once per run and
279	// handed to `collectSignals`. Exported so the construction itself is testable:
280	// the collectors' `ctx.X ?? null` seam makes them unit-testable with a hand-built
281	// ctx, which is exactly why a key nothing here populates can read as "collector
282	// works" forever. Assert against THIS, not a hand-built shape.
283	// `root` is the Action-side checkout: the manifest version, the local-pack
284	// presence and the configured retention are all read from it (signals/local.mjs),
285	// because a scheduled run already has the tree on disk and an API round-trip
286	// would buy nothing.
287	export function buildSignalContext({ root, repo, defaultBranch, now, sinceIso, config, fleet = null, packConfigFor = () => ({}) }) {
288	  const local = localSignalContext(root, { packIds: config.packs ?? [], packConfigFor });
289	  return {
290	    repo, defaultBranch, now, sinceIso, config,
291	    activePacks: config.packs, fleet,
292	    manifestVersion: local.manifestVersion,
293	    hasLocalPacks: local.hasLocalPacks,
294	    retentionDays: local.retentionDays,
295	  };
296	}
