298	// --- CLI: the thin I/O shell the vendored workflow invokes -------------------
299	// Wires the run-ledger read, signal collectors, and issue I/O around planRun,
300	// then acts on each decision (file a labeled dispatch issue, or run an inline
301	// worker) and prints the job summary. All GitHub access here is the Action's
302	// GITHUB_TOKEN — the one sanctioned non-MCP surface (DESIGN §10).
303	
304	// The task family's issues (state=all) via the search API, filtered to exact
305	// prefix — the input planDispatch's exactly-once / at-most-one-open guards read.
306	async function existingIssuesViaSearch(gh, repo, pack, task) {
307	  const q = encodeURIComponent(`repo:${repo} in:title "${DISPATCH_PREFIX} ${pack}/${task}"`);
308	  const { status, json } = await gh(`/search/issues?q=${q}&per_page=100`);
309	  if (status !== 200 || !Array.isArray(json?.items)) return [];
310	  const prefix = `${DISPATCH_PREFIX} ${pack}/${task} `;
311	  return json.items
312	    .filter((i) => `${(i.title ?? '').trim()} `.startsWith(prefix))
313	    .map((i) => ({ number: i.number, title: i.title, state: i.state }));
314	}
