316	// Every OPEN dispatch issue in the repo, with the labels / age / comment count the
317	// maintenance pass reads. Separate from existingIssuesViaSearch, which is per task
318	// family and state=all for the filing guards; this one is repo-wide and open-only.
319	export async function openDispatchIssuesViaSearch(gh, repo) {
320	  const q = encodeURIComponent(`repo:${repo} is:issue is:open in:title "${DISPATCH_PREFIX}"`);
321	  const { status, json } = await gh(`/search/issues?q=${q}&per_page=100`);
322	  if (status !== 200 || !Array.isArray(json?.items)) return [];
323	  return json.items.map((i) => ({
324	    number: i.number, title: i.title, labels: i.labels ?? [],
325	    created_at: i.created_at, updated_at: i.updated_at, comments: i.comments ?? 0,
326	  }));
327	}
