329	// The per-run maintenance pass over open dispatch issues (DESIGN §4 lifecycle,
330	// §5 recovery). Three backstops, in this order:
331	//   1. STALE — open past ~2 of its own scheduling periods → escalation comment,
332	//      drop the ready label (so it stops being armed), add `needs-human`.
333	//   2. DEAD CLAIM — `agent-running` with no activity for ~3h → the session that
334	//      claimed it died; comment, drop `agent-running`, add `needs-human`.
335	//   3. RE-ARM — armed but untouched past the grace window → the trigger event was
336	//      lost, so remove and re-add its ready label to emit a fresh one.
337	// Stale wins over re-arm: rearmDispatchIssues already excludes the stale set, so an
338	// issue converging to triage is never re-armed back into circulation.
339	//
340	// This is the ONLY recovery path for a missed label event or a dead session. The
341	// executor no longer sweeps other issues — one session runs exactly the one issue
342	// that triggered it — so recovery had to become a decision in code here, running
343	// once per scheduler run, rather than agent judgment replicated across every
344	// concurrently-triggered session.
345	export async function maintainDispatchIssues(gh, repo, now, { labelsEnsured = false } = {}) {
346	  const open = await openDispatchIssuesViaSearch(gh, repo);
347	  const none = { stale: [], deadClaims: [], rearmed: [] };
348	  if (!open.length) return none;
349	
350	  const stale = staleDispatchIssues(open, now);
351	  const staleNumbers = new Set(stale.map((i) => i.number));
352	  const deadClaims = staleClaimedDispatchIssues(open, now).filter((i) => !staleNumbers.has(i.number));
353	  const rearm = rearmDispatchIssues(open, now);
354	  if (!stale.length && !deadClaims.length && !rearm.length) return none;
355	
356	  // Applying a label 422s when it does not exist, so guarantee them first — an
357	  // idle run never gets here, so this costs nothing on the common path.
358	  if (!labelsEnsured) await ensureLabels(gh, repo, SCHEDULER_LABELS);
359	
360	  const escalate = async (issue, body, dropLabel) => {
361	    await gh(`/repos/${repo}/issues/${issue.number}/comments`, { method: 'POST', body: { body } });
362	    if (dropLabel) await gh(`/repos/${repo}/issues/${issue.number}/labels/${encodeURIComponent(dropLabel)}`, { method: 'DELETE' });
363	    await gh(`/repos/${repo}/issues/${issue.number}/labels`, { method: 'POST', body: { labels: [NEEDS_HUMAN_LABEL] } });
364	  };
365	
366	  for (const issue of stale) {
367	    await escalate(issue, staleEscalationComment(issue), readyLabelOn(issue));
368	    console.log(`- escalated stale dispatch #${issue.number} to ${NEEDS_HUMAN_LABEL}`);
369	  }
370	
371	  for (const issue of deadClaims) {
372	    await escalate(issue, staleClaimComment(issue), AGENT_RUNNING_LABEL);
373	    console.log(`- reclaimed dead ${AGENT_RUNNING_LABEL} claim on #${issue.number} → ${NEEDS_HUMAN_LABEL}`);
374	  }
375	
376	  for (const issue of rearm) {
377	    const ready = readyLabelOn(issue);
378	    const del = await gh(`/repos/${repo}/issues/${issue.number}/labels/${encodeURIComponent(ready)}`, { method: 'DELETE' });
379	    if (del.status >= 300) { console.log(`! could not un-label #${issue.number} to re-arm it: ${del.status}`); continue; }
380	    const add = await gh(`/repos/${repo}/issues/${issue.number}/labels`, { method: 'POST', body: { labels: [ready] } });
381	    if (add.status >= 300) console.log(`! re-arm of #${issue.number} dropped its ${ready} label: ${add.status}`);
382	    else console.log(`- re-armed #${issue.number} (${ready}) — its trigger event never landed`);
383	  }
384	
385	  return {
386	    stale: stale.map((i) => i.number),
387	    deadClaims: deadClaims.map((i) => i.number),
388	    rearmed: rearm.map((i) => i.number),
389	  };
390	}
