392	// Ensure the dispatch labels exist before any is applied — GitHub 422s when you
393	// apply an unknown label (it never creates one on demand), so the scheduler, as the
394	// thing that assigns them, guarantees them here. Idempotent (201 created / 422 already
395	// exists are both success) and self-healing (a deleted label reappears next run), which
396	// is why no separate one-off label-creation step is needed. Exported for the run tests.
397	export async function ensureLabels(gh, repo, labels) {
398	  for (const { name, color, description } of labels) {
399	    const res = await gh(`/repos/${repo}/labels`, { method: 'POST', body: { name, color, description } });
400	    if (res.status === 201) continue;                       // created to spec — nothing further
401	    if (res.status === 422) {
402	      // The NAME is taken; that says nothing about the colour or description. A
403	      // label GitHub auto-created (applying an unknown name to an issue mints it
404	      // grey `ededed`, no description) would keep those defaults for good, because
405	      // POST 422s forever. So reconcile the shape, not just the existence — that
406	      // is what makes the self-healing claim above true for drift and not only for
407	      // deletion. PATCH is idempotent: an already-correct label is a no-op write.
408	      const fix = await gh(`/repos/${repo}/labels/${encodeURIComponent(name)}`, {
409	        method: 'PATCH', body: { color, description },
410	      });
411	      if (fix.status !== 200) console.log(`! could not reconcile label "${name}": ${fix.status}`);
412	      continue;
413	    }
414	    console.log(`! could not ensure label "${name}": ${res.status}`);
415	  }
416	}
