430	  // The dormancy gate, before ANY of it: the run-ledger read, the task discovery,
431	  // the signal collection, the issue I/O, the dispatch maintenance. planRun holds
432	  // the same verdict (one predicate, both call sites) and would return an empty
433	  // plan — but a dormant repo should not pay for the reads that produce it, and
434	  // the maintenance pass below writes to issues, which is exactly the ceremony
435	  // dormancy exists to stop.
436	  //
437	  // Exit 0, deliberately. The run enters the success ledger and the watermark
438	  // advances past these slots, so waking a project up does NOT replay the months
439	  // it slept through — it simply starts scheduling again from now. Slots skipped
440	  // while dormant are skipped on purpose, not deferred.
441	  if (isDormant(config)) {
442	    console.log('## Claudinite scheduler\n');
443	    console.log('- this project declares itself dormant ("dormant": true in .claudinite-checks.json) — no tasks evaluated, no work dispatched');
444	    return;
445	  }
