568	    // `deferred` — another task claimed this run exclusively. The record says the
569	    // precondition wanted work; this is the one place that decides none of it
570	    // happens, so nothing below (preprocessing subprocess, dispatch issue) runs.
571	    if (!rec.run || rec.deferred) continue;
572	    const taskObj = tasks.find((t) => t.pack === rec.pack && t.id === rec.task);
573	    const decl = taskObj.decl;
574	
575	    // Stage 1 — preprocessing (DESIGN §3): run the declared command as a subprocess
576	    // bounded by its timeout, before any agent. Its cwd is the task dir; the repo
577	    // root + slot context ride in via CLAUDINITE_* env.
578	    if (rec.preprocessing) {
579	      // A per-run signal path the worker writes to REQUEST the agent stage
580	      // (conditional handoff, §3). Clear any stale one first so a prior run can't
581	      // spuriously escalate this one.
582	      const requestPath = agentRequestPath(rec);
583	      clearAgentRequest(requestPath);
584	      // The child's own output is echoed live inside a collapsible Actions group, so
585	      // the run log says what the worker did instead of only whether it exited zero.
586	      // Grouped because several tasks can preprocess in one run and their output would
587	      // otherwise interleave into one unattributable wall; live because a worker killed
588	      // at its timeout takes any buffered output with it.
589	      console.log(`::group::preprocessing ${rec.pack}/${rec.task} [${rec.slotId}]`);
590	      const result = await runPreprocessing(decl.agent_preprocessing, {
591	        taskDir: taskObj.taskDir,
592	        env: {
593	          ...process.env,
594	          CLAUDINITE_REPO_ROOT: root,
595	          CLAUDINITE_REPO: repo,
596	          CLAUDINITE_DEFAULT_BRANCH: defaultBranch ?? '',
597	          CLAUDINITE_SLOT_ID: rec.slotId,
598	          CLAUDINITE_PACK: rec.pack,
599	          CLAUDINITE_TASK: rec.task,
600	          CLAUDINITE_REQUEST_AGENT: requestPath,
601	        },
602	        timeoutSeconds: decl.agent_preprocessing_timeout,
603	      });
604	      console.log('::endgroup::');
605	      rec.preprocessResult = { ok: result.ok, timedOut: result.timedOut, code: result.code };
606	      if (!result.ok) {
607	        const why = preprocessingFailure(result);
608	        console.log(`! preprocessing ${rec.pack}/${rec.task} [${rec.slotId}]: ${why}`);
609	        const extra = result.stderr?.trim() ? [`stderr tail: ${result.stderr.trim().split('\n').slice(-3).join(' / ')}`] : [];
610	        // Repeat the tail OUTSIDE the group: Actions renders a group collapsed, so a
611	        // failure whose only evidence sits inside one still reads as unexplained.
612	        for (const line of extra) console.log(`  ${line}`);
613	        await fileNeedsHuman(rec, why, extra);
614	        clearAgentRequest(requestPath);
615	        continue; // never hand off to an agent after a failed preprocessing
616	      }
617	      // Success. An agentless task is done (no issue on success, as the old inline
618	      // was quiet). An agentful one hands off ONLY when the worker requested the
619	      // agent (conditional escalation, §3): a task that absorbs its work into
620	      // preprocessing stays quiet on the nights nothing needs judgment.
621	      const requested = agentRequested(requestPath);
622	      // Read the payload BEFORE clearing: the artifacts this run created and the
623	      // condition that woke the agent, which the dispatch issue records so the agent
624	      // never has to search for them by name or re-derive why it is there. Both are
625	      // null for a worker that named neither — absence is reported as absence.
626	      const payload = requested ? readAgentRequest(requestPath) : null;
627	      rec.delivered = payload?.delivered ?? null;
628	      rec.escalationReason = payload?.reason ?? null;
629	      clearAgentRequest(requestPath);
630	      rec.agentRequested = requested;
631	      console.log(`preprocessing ${rec.pack}/${rec.task} [${rec.slotId}]: ok${rec.inline ? '' : requested ? ' (agent requested)' : ' (no agent needed)'}`);
632	      if (rec.inline) continue;
633	      if (requested && rec.dispatch?.action === 'create') await fileHandoff(rec, taskObj);
634	      continue;
635	    }
636	
637	    // No preprocessing. An agentless task with no preprocessing does nothing — the
638	    // contract now forbids it (agent_model:none REQUIRES agent_preprocessing, so
639	    // the in-process inline worker path is retired, DESIGN §4). Defensive no-op
640	    // should one slip past validation.
641	    if (rec.inline) {
642	      console.log(`- ${rec.pack}/${rec.task}: agentless with no preprocessing — nothing to run (contract-forbidden)`);
643	      continue;
644	    }
645	    // Agent task with no preprocessing → today's immediate labeled dispatch.
646	    if (rec.dispatch?.action === 'create') await fileHandoff(rec, taskObj);
647	  }
648	
649	  // Maintenance over the open dispatch issues, AFTER this run's filings: the
650	  // issues just filed are seconds old, so the grace window keeps them out of the
651	  // re-arm set and only the previous cycles' leftovers are considered.
652	  await maintainDispatchIssues(gh, repo, now, { labelsEnsured });
653	
654	  console.log('## Claudinite scheduler\n');
655	  console.log(renderSummary(evaluations) || '- no tasks due');
656	
657	  // The machine-readable half of the same story (run-record.mjs): one line per due
658	  // task saying what this run DID with it — dispatched an agent, ran it as
659	  // preprocessing only, skipped it on its precondition, failed it, or deferred it.
660	  // Printed AFTER the action loop, so each line reports what happened rather than
661	  // what was planned, and read back by the usage fold to count task invocations.
662	  // Nothing else in the scheduler depends on it: this is a record, not a signal.
663	  if (evaluations.length) console.log(`\n${renderTaskRuns(evaluations)}`);
664	}
665	
666	// Run only when invoked directly (the workflow's `node run.mjs`), never on import.
667	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
668	  main().catch((e) => { console.error(e); process.exit(1); });
669	}
670

