1	// The usage fold's SECOND source: the scheduler's own Actions runs
2	// (skill-usage-metrics DESIGN §4.2). Every scheduler run prints one machine-readable
3	// record per due task saying what it did with it — dispatched an agent, ran it as
4	// deterministic preprocessing only, skipped it on its precondition, failed it, or
5	// deferred it. This module reads those records back out of the run logs.
6	//
7	// It lives in this task's folder because nothing else uses it, and it holds no
8	// counting logic: it turns "runs since the watermark" into `[{ date, pack, task,
9	// outcome }]`, and fold-usage.mjs does the arithmetic.
10	//
11	// FORWARD-ONLY, past a watermark — unlike the capture files, which the fold
12	// re-reads from scratch every night. The reason is the source, not the taste: the
13	// logs branch is local git (one tree read plus one blob read, no budget to spend),
14	// while these are paged REST reads over a rate-limited API, two calls per run, and
15	// re-reading a 10-day window every night would cost ~20x the calls for an identical
16	// answer. So each fold reads only what is new and the aggregate carries how far it
17	// got. The cost is stated where the trade is made (fold-usage.mjs `foldTaskRuns`):
18	// a counting bug fixed later applies from the fix forward, it does not heal history.
19	//
20	// FAIL-SOFT. Every failure here — an unreadable ledger, a log that 404s, a run whose
21	// jobs cannot be listed — degrades this ONE source to "nothing new this run" and
22	// leaves the watermark where it was, so the next fold retries the same runs. The
23	// skill and check counts do not depend on it and must not be lost with it.
24	
25	import { SCHEDULER_WORKFLOW_FILE } from '../../../../engine/scheduler/signals/gh.mjs';
26	import { parseTaskRuns } from '../../../../engine/scheduler/run-record.mjs';
27	
28	const API = process.env.GITHUB_API_URL || 'https://api.github.com';
29	
30	// How many runs one fold will pull logs for. An hourly scheduler files ~24 runs a
31	// day, so this is ~10 days of catch-up in a single pass at two API calls each —
32	// enough to absorb a long fold outage, bounded so a pathological backlog cannot eat
33	// the run's whole rate budget in one go. A truncated pass advances the watermark to
34	// the last run it read, so the next fold continues from there; the caller LOGS the
35	// remainder rather than leaving a silent cap.
36	export const MAX_RUNS_PER_FOLD = 240;
37	
38	// How far back the FIRST fold looks when the aggregate carries no run watermark yet.
39	// Deliberately short: there is no history to reconstruct here, only a series to
40	// start, and a repo adopting this should not spend hundreds of API calls back-filling
41	// days whose numbers nobody will read.
42	export const FIRST_FOLD_LOOKBACK_DAYS = 2;
43	
44	// A tiny REST reader. Separate from the scheduler's `makeGh` because that one parses
45	// JSON and the job-log endpoint answers with a redirect to plain text; `fetchImpl` is
46	// injected so the tests drive both shapes without a network.
47	export function makeReader({ token = process.env.GITHUB_TOKEN, api = API, fetchImpl = fetch } = {}) {
48	  const headers = {
49	    accept: 'application/vnd.github+json',
50	    'x-github-api-version': '2022-11-28',
51	    'user-agent': 'claudinite-usage-fold',
52	    ...(token ? { authorization: `Bearer ${token}` } : {}),
53	  };
54	  return {
55	    async json(path) {
56	      const res = await fetchImpl(`${api}${path}`, { headers });
57	      if (res.status !== 200) return null;
58	      try { return await res.json(); } catch { return null; }
59	    },
60	    async text(path) {
61	      const res = await fetchImpl(`${api}${path}`, { headers });
62	      if (res.status !== 200) return null;
63	      try { return await res.text(); } catch { return null; }
64	    },
65	  };
66	}
67	
68	export const lookbackFrom = (nowIso, days = FIRST_FOLD_LOOKBACK_DAYS) =>
69	  new Date(new Date(nowIso).getTime() - days * 86400000).toISOString();
70	
71	// The scheduler runs to read this fold: completed runs started strictly after the
72	// watermark, oldest first.
73	//
74	// Only COMPLETED runs — an in-progress run's log is still being written, and the
75	// fold itself runs inside one (its own). That is safe against a gap because the
76	// workflow serializes on a concurrency group: a prior run has finished before the
77	// current one starts, so "completed and newer than the watermark" cannot skip a run
78	// that was still running when an earlier fold looked.
79	export async function schedulerRuns(reader, repo, { since, workflow = SCHEDULER_WORKFLOW_FILE, maxPages = 5 }) {
80	  const runs = [];
81	  for (let page = 1; page <= maxPages; page++) {
82	    const path = `/repos/${repo}/actions/workflows/${workflow}/runs`
83	      + `?status=completed&per_page=100&page=${page}&created=%3E%3D${encodeURIComponent(String(since).slice(0, 10))}`;
84	    const json = await reader.json(path);
85	    const batch = json?.workflow_runs;
86	    if (!Array.isArray(batch) || batch.length === 0) break;
87	    for (const run of batch) {
88	      const at = run.run_started_at || run.created_at;
89	      if (!at || !run.id) continue;
90	      if (at <= since) continue;           // already folded (the `created` filter is day-grained)
91	      runs.push({ id: run.id, startedAt: at });
92	    }
93	    if (batch.length < 100) break;
94	  }
95	  // The API answers newest-first; fold oldest-first so a truncated pass leaves a
96	  // watermark the next fold can continue from.
97	  return runs.sort((a, b) => (a.startedAt < b.startedAt ? -1 : a.startedAt > b.startedAt ? 1 : a.id - b.id));
98	}
99	
100	// One run's whole log text — every job's, concatenated. Two calls: list the jobs,
101	// then read each one's log. A job whose log cannot be read contributes nothing
102	// rather than sinking the run.
103	export async function runLogText(reader, repo, runId) {
104	  const json = await reader.json(`/repos/${repo}/actions/runs/${runId}/jobs?per_page=100`);
105	  const jobs = Array.isArray(json?.jobs) ? json.jobs : [];
106	  const texts = [];
107	  for (const job of jobs) {
108	    if (!job?.id) continue;
109	    const text = await reader.text(`/repos/${repo}/actions/jobs/${job.id}/logs`);
110	    if (text) texts.push(text);
111	  }
112	  return texts.join('\n');
113	}
114	
115	// The whole read: `{ records, watermark, remaining }`.
116	//   records   — [{ date, pack, task, outcome }], the date being the run's UTC start
117	//               day, which is the day the work was scheduled for.
118	//   watermark — the new `runsFoldedThrough`, or the old one when nothing was read.
119	//   remaining — runs left unread because of the per-fold cap (0 normally). The
120	//               caller logs it; a cap that truncates silently reads as "covered
121	//               everything" when it did not.
122	export async function readTaskRuns({ reader, repo, since, now, max = MAX_RUNS_PER_FOLD }) {
123	  const from = since || lookbackFrom(now);
124	  let runs;
125	  try {
126	    runs = await schedulerRuns(reader, repo, { since: from });
127	  } catch {
128	    return { records: [], watermark: since, remaining: 0, error: 'the scheduler run ledger could not be read' };
129	  }
130	  const remaining = Math.max(0, runs.length - max);
131	  const records = [];
132	  let watermark = since;
133	  for (const run of runs.slice(0, max)) {
134	    let text = '';
135	    try { text = await runLogText(reader, repo, run.id); } catch { text = ''; }
136	    const date = run.startedAt.slice(0, 10);
137	    for (const rec of parseTaskRuns(text)) records.push({ date, ...rec });
138	    // Advance past a run whose log held no records too: an idle hour (nothing due)
139	    // legitimately prints none, and re-reading it every night forever would be the
140	    // one way this stays expensive.
141	    watermark = run.startedAt;
142	  }
143	  return { records, watermark, remaining };
144	}
