1	// The dispatch issue — how a due (task, slot) becomes exactly-once, bounded,
2	// recoverable agent work (per-project-scheduling DESIGN §4). This module is the
3	// PURE half: issue identity (title/body/parse) and the create / skip / suppress
4	// decision over the issues that already exist. A thin scheduler shell does the
5	// GitHub I/O (search state=all, create, label, comment) and applies the verdict
6	// — the "should I file this" decision is always code here, never the shell's
7	// judgment (the same split the fleet planner uses).
8	//
9	// All behavior-defining content (agent_model, expected_outcome, agent_instructions) is read from the
10	// tracked task files, never from the issue — the body only points at the task
11	// file and carries the precondition's binding Context (DESIGN §4).
12	
13	// The labels this machinery drives. `ready-for-agent` is what the executor
14	// routine fires on; `needs-human` is the single triage state every anomaly
15	// converges to (DESIGN §4 lifecycle). Kept here as the shared source for the
16	// scheduler side; the executor reuses these plus `agent-running`.
17	export const READY_LABEL = 'ready-for-agent';
18	// A fleet-scoped task (session_scope: 'fleet') dispatches to a DISTINCT ready
19	// label so a separate, broader-scoped executor routine runs it — keeping the
20	// fleet-wide session grant off every ordinary project's self executor (the
21	// per-project-scheduling fleet/self split). Only tasks that reach other repos use
22	// this; today just growth-promote.
23	export const READY_FLEET_LABEL = 'ready-for-agent-fleet';
24	export const AGENT_RUNNING_LABEL = 'agent-running';
25	export const NEEDS_HUMAN_LABEL = 'needs-human';
26	export const WORKFLOW_FAILURE_LABEL = 'workflow-failure';
27	
28	// The ready label a task's dispatch is filed under, from its declared
29	// session_scope ('self' default → READY_LABEL; 'fleet' → READY_FLEET_LABEL). The
30	// one place this mapping lives, so the scheduler (which files) and any reader stay
31	// in sync.
32	export const readyLabelForScope = (scope) => (scope === 'fleet' ? READY_FLEET_LABEL : READY_LABEL);
33	
34	// The full label set the scheduler + executor drive, each with the colour and
35	// description a bootstrap one-off would have given it. The scheduler ENSURES every
36	// one exists (create-if-missing, idempotent) right before it dispatches — so there
37	// is no separate label-creation step to run or forget, and a deleted label
38	// self-heals on the next run. This is load-bearing, not cosmetic: GitHub does not
39	// create a label when you apply it (the issues API 422s on an unknown label), so
40	// the thing that assigns a label must guarantee it first — the
41	// gha/label-create-before-add principle, enforced in code here.
42	export const SCHEDULER_LABELS = [
43	  { name: READY_LABEL, color: '0e8a16', description: 'Claudinite scheduler: dispatch issue ready for the (self-scoped) executor to run' },
44	  { name: READY_FLEET_LABEL, color: '1d76db', description: 'Claudinite scheduler: dispatch issue ready for the FLEET-scoped executor (a task that reaches other repos)' },
45	  { name: AGENT_RUNNING_LABEL, color: 'fbca04', description: 'Claudinite scheduler: the executor has claimed this issue and is running it' },
46	  { name: NEEDS_HUMAN_LABEL, color: 'd93f0b', description: 'Claudinite scheduler: an anomaly that converged here for human triage' },
47	  { name: WORKFLOW_FAILURE_LABEL, color: 'b60205', description: 'Claudinite scheduler: a scheduler run or task failed' },
48	];
49	
50	// Title: `[claudinite-task] <pack>/<task> <slot-id>` (DESIGN §4). The prefix is
51	// what keeps these issues invisible to the scheduler's own signals (self-trigger
52	// exclusion) and searchable as a family.
53	export const DISPATCH_PREFIX = '[claudinite-task]';
54	
55	export const dispatchTitle = ({ pack, task, slotId }) => `${DISPATCH_PREFIX} ${pack}/${task} ${slotId}`;
56	
57	// The (pack, task) family key — every slot's title for one task starts with
58	// `<key> ` (the trailing space before the slot id is load-bearing: it stops
59	// `foo/extract` from matching `foo/extract-more`).
60	export const dispatchTaskKey = ({ pack, task }) => `${DISPATCH_PREFIX} ${pack}/${task}`;
61	
62	// pack and task ids are single path segments (no slash, no space); the slot id
63	// is the trailing non-space token.
64	const DISPATCH_TITLE_RE = /^\[claudinite-task\]\s+([^/\s]+)\/([^/\s]+)\s+(\S+)$/;
65	
66	export function parseDispatchTitle(title) {
67	  const m = DISPATCH_TITLE_RE.exec(String(title ?? '').trim());
68	  return m ? { pack: m[1], task: m[2], slotId: m[3] } : null;
69	}
70	
71	// Is this a scheduler dispatch issue? The self-trigger exclusion the signal
72	// collectors apply so the scheduler never sees its own dispatch issues as work.
73	export const isDispatchTitle = (title) => parseDispatchTitle(title) !== null;
74	
75	// The dispatch issue body (DESIGN §4). First line is the task-file path — the
76	// only thing the executor reads to locate the worker; everything below is human
77	// framing plus the precondition's binding Context. The Context block is emitted
78	// only when the precondition produced lines (an empty scope has nothing to bind).
79	// The `### Delivered` section — what this run's preprocessing created, by identity. It is
80	// the agent's only source for those artifacts.
81	//
82	// Absence is meaningful: no section means preprocessing created nothing, so never write a
83	// placeholder here.
84	export function deliveredLines(delivered) {
85	  const { branch = null, pr = null, merged = false } = delivered ?? {};
86	  if (!branch && !pr) return [];
87	  return [
88	    '### Delivered by preprocessing',
89	    'The artifacts this run created — the ones to work on.',
90	    '',
91	    ...(pr ? [`- PR: #${pr}${merged ? ' (already merged — open your own PR for further work)' : ' (open)'}`] : []),
92	    ...(branch ? [`- Branch: \`${branch}\``] : []),
93	  ];
94	}
95	
96	// The `### Why the agent is here` section — which of preprocessing's escalation
97	// conditions fired. The worker knows it exactly; without this the agent re-derives it
98	// from the repo, and a re-derivation that disagrees with the truth is how a run ends up
99	// reporting "preprocessing created nothing" about a cycle that just merged a PR
100	// (EdFringeAllocator#82).
101	//
102	// The condition and its counts, never the findings — those stay in the repo (DESIGN §3).
103	// Absence is meaningful here too: a worker too old to name a reason says nothing, and
104	// the agent falls back to its task file's own sweep.
105	export function escalationLines(reason) {
106	  const { code = null, detail = null } = reason ?? {};
107	  if (!code && !detail) return [];
108	  return [
109	    '### Why the agent is here',
110	    'The condition preprocessing escalated on. Start here; the findings themselves are in the repo, not this issue.',
111	    '',
112	    `- ${detail || code}${detail && code ? ` (\`${code}\`)` : ''}`,
113	  ];
114	}
115	
116	export function dispatchBody({ taskPath, pack, task, slotId, context = [], delivered = null, reason = null }) {
117	  const lines = [taskPath, ''];
118	  if (context.length) {
119	    lines.push(
120	      `Execute the Claudinite task above (pack \`${pack}\`, task \`${task}\`, slot \`${slotId}\`).`,
121	      'The Context section below is binding scope — do not re-decide it.',
122	      '',
123	      '### Context',
124	    );
125	    for (const c of context) lines.push(`- ${c}`);
126	  } else {
127	    lines.push(`Execute the Claudinite task above (pack \`${pack}\`, task \`${task}\`, slot \`${slotId}\`).`);
128	  }
129	  // Why first, then what: the reason is what decides which of the task file's sections
130	  // the agent actually needs, and the artifacts are what it does that work on.
131	  const why = escalationLines(reason);
132	  if (why.length) lines.push('', ...why);
133	  const del = deliveredLines(delivered);
134	  if (del.length) lines.push('', ...del);
135	  return lines.join('\n') + '\n';
136	}
137	
138	// The filing decision for one due (task, slot), given `existing` — the issues
139	// the shell fetched for this task's family (title starts with the task key),
140	// each `{ number, title, state }` with state 'open' | 'closed'. Two guards
141	// (DESIGN §4):
142	//   - exactly-once per (task, slot): a state=all title match for THIS slot → skip
143	//     (makes double-runs and crash-retries safe).
144	//   - at-most-one-open per task: any OPEN family issue (any slot) suppresses a
145	//     new filing → an executor outage accumulates at most one issue per task.
146	// Otherwise: create (the shell files it labeled with `readyLabel` — the
147	// self/fleet ready label the task's scope resolves to, default `ready-for-agent`).
148	export function planDispatch({ existing = [], pack, task, slotId, readyLabel = READY_LABEL }) {
149	  const title = dispatchTitle({ pack, task, slotId });
150	  const keyPrefix = `${dispatchTaskKey({ pack, task })} `;
151	  const family = existing.filter((i) => `${(i.title ?? '').trim()} `.startsWith(keyPrefix));
152	
153	  if (family.some((i) => (i.title ?? '').trim() === title)) {
154	    return { action: 'skip', reason: `dispatch issue for slot ${slotId} already exists (exactly-once)` };
155	  }
156	  const open = family.find((i) => i.state === 'open');
157	  if (open) {
158	    return { action: 'suppress', openIssue: open.number, reason: `an open dispatch issue (#${open.number}) already covers ${pack}/${task}` };
159	  }
160	  return { action: 'create', title, label: readyLabel, reason: `no dispatch issue yet for ${pack}/${task} slot ${slotId}` };
161	}
162	
163	// The period one slot id represents, from its leading kind char (h/d/w/m). Used
164	// only for the stale-issue backstop's threshold; daily-family slots all span a
165	// day. Monthly uses 31 days so the ~2-period threshold never fires early in a
166	// long month.
167	const SLOT_PERIOD_MS = { h: 3600e3, d: 86400e3, w: 7 * 86400e3, m: 31 * 86400e3 };
168	
169	function slotPeriodMs(slotId) {
170	  return SLOT_PERIOD_MS[String(slotId ?? '')[0]] ?? null;
171	}
172	
173	// GitHub hands labels back as objects on the issues/search APIs and as bare
174	// strings in some fixtures; accept either.
175	const labelNames = (issue) =>
176	  (issue?.labels ?? []).map((l) => (typeof l === 'string' ? l : l?.name)).filter(Boolean);
177	
178	// Open dispatch issues older than `factor` of their own period (DESIGN §4: ~2
179	// periods) — the scheduler's backstop when no executor session drains them. The
180	// shell adds the escalation comment + `needs-human` to each. `issue.created_at`
181	// is the ISO string GitHub returns; a title that doesn't parse (or an unknown
182	// slot kind) is never stale here.
183	//
184	// ESCALATION IS ONCE. Escalating only adds a label and leaves the issue OPEN, so
185	// an issue that already carries `needs-human` still matches every later run —
186	// and the shell re-posts the identical comment on each. Skipping the already
187	// escalated is what makes "converge to a single visible state" true rather than
188	// a state the scheduler keeps re-announcing every hour, forever.
189	//
190	// A CLAIMED issue is not this sweep's to judge either. `agent-running` means a
191	// session engaged; whether that claim is dead is `staleClaimedDispatchIssues`'s
192	// question, and it says so in its own words. Without this the two overlap on an
193	// old claimed issue, the shell's stale-first ordering wins, and the issue is
194	// told "no executor session ran it" about a session that demonstrably ran.
195	export function staleDispatchIssues(openIssues = [], now, { factor = 2 } = {}) {
196	  const nowMs = new Date(now).getTime();
197	  return openIssues.filter((issue) => {
198	    const parsed = parseDispatchTitle(issue.title);
199	    if (!parsed) return false;
200	    const names = labelNames(issue);
201	    if (names.includes(NEEDS_HUMAN_LABEL) || names.includes(AGENT_RUNNING_LABEL)) return false;
202	    const period = slotPeriodMs(parsed.slotId);
203	    if (period === null) return false;
204	    return nowMs - new Date(issue.created_at).getTime() > factor * period;
205	  });
206	}
207	
208	// The escalation comment the shell posts on a stale dispatch issue.
209	export function staleEscalationComment(issue) {
210	  const parsed = parseDispatchTitle(issue.title);
211	  const which = parsed ? `${parsed.pack}/${parsed.task} (slot ${parsed.slotId})` : 'this task';
212	  return `This dispatch issue for ${which} has stayed open past ~2 of its scheduling periods without being executed — `
213	    + `no executor session ran it. Labeling \`${NEEDS_HUMAN_LABEL}\` for triage.`;
214	}
215	
216	// --- re-arming a lost trigger ------------------------------------------------
217	// The label event is the executor's ONLY trigger, and a delivery can be lost: the
218	// routine was down or paused, or a session died before it claimed. The issue then
219	// sits armed forever, because the label is already applied and GitHub emits
220	// `labeled` only on a fresh add. So the scheduler re-arms it — remove the ready
221	// label, add it back — which emits a new event.
222	//
223	// This is the recovery that used to live in the executor's drain sweep, moved into
224	// deterministic code. The sweep had EVERY triggered session also process every
225	// OTHER armed issue, so one scheduler run filing N dispatches produced N sessions
226	// each racing over the same N issues, and the claim swap could not stop it (every
227	// session read the work list before any claim landed). That is the
228	// duplicate-execution bug: the same dispatch run two or three times over,
229	// duplicate tracker issues, duplicate PRs making the same changes. Recovery
230	// belongs here, where it is a decision in code that runs once per scheduler run.
231	
232	const READY_LABELS = new Set([READY_LABEL, READY_FLEET_LABEL]);
233	
234	// The ready label an issue currently carries, or null. Re-arming reapplies THIS
235	// one, so a fleet dispatch is never re-armed as a self dispatch (which would hand
236	// it to an executor whose session lacks the cross-repo reach it needs).
237	export function readyLabelOn(issue) {
238	  return labelNames(issue).find((n) => READY_LABELS.has(n)) ?? null;
239	}
240	
241	// The open dispatch issues whose trigger evidently never landed. Re-arm only an
242	// issue that is:
243	//   - a dispatch issue (parseable title) still carrying a ready label;
244	//   - unclaimed — no `agent-running` (a live session claims before it dispatches)
245	//     and not already converged to `needs-human`;
246	//   - uncommented — the executor comments on every exit path, so a comment means
247	//     some session engaged and this is not a lost event; and
248	//   - past `graceMs` (default 20m), comfortably beyond session spin-up, so a
249	//     session already on its way is never handed a rival.
250	// A stale issue is never re-armed: it is on its way to `needs-human`, and re-arming
251	// one would loop forever. That backstop is also what bounds this — an executor that
252	// stays down is re-armed each run until ~2 periods, then converges to triage.
253	// Dispatch issues left claimed by a session that died mid-run: `agent-running`
254	// with no activity for `idleMs` (~3h). Converging these used to be the executor's
255	// own step 6, which meant every concurrently-triggered session swept them and
256	// commented on the same issue — the duplicate-work bug in miniature. It is code
257	// here for the same reason the re-arm is.
258	//
259	// Scoped to `[claudinite-task]` dispatch issues deliberately (the title parse is
260	// what enforces it): a task may put `agent-running` on an issue IT owns — a
261	// request its pipeline has claimed, which stays claimed while its PR is in review,
262	// far longer than 3h — and only that task knows when its own claim is stale.
263	export function staleClaimedDispatchIssues(openIssues = [], now, { idleMs = 3 * 3600e3 } = {}) {
264	  const nowMs = new Date(now).getTime();
265	  return openIssues.filter((issue) => {
266	    if (!parseDispatchTitle(issue.title)) return false;
267	    const names = labelNames(issue);
268	    if (!names.includes(AGENT_RUNNING_LABEL) || names.includes(NEEDS_HUMAN_LABEL)) return false;
269	    return nowMs - new Date(issue.updated_at ?? issue.created_at).getTime() > idleMs;
270	  });
271	}
272	
273	// The comment the shell posts when it reclaims a dead session's claim.
274	export function staleClaimComment(issue) {
275	  const parsed = parseDispatchTitle(issue.title);
276	  const which = parsed ? `${parsed.pack}/${parsed.task} (slot ${parsed.slotId})` : 'this task';
277	  return `This dispatch issue for ${which} has carried \`${AGENT_RUNNING_LABEL}\` for over 3h with no activity — `
278	    + `the executor session that claimed it never converged it. Labeling \`${NEEDS_HUMAN_LABEL}\` for triage.`;
279	}
280	
281	export function rearmDispatchIssues(openIssues = [], now, { graceMs = 20 * 60e3 } = {}) {
282	  const nowMs = new Date(now).getTime();
283	  const stale = new Set(staleDispatchIssues(openIssues, now).map((i) => i.number));
284	  return openIssues.filter((issue) => {
285	    if (!parseDispatchTitle(issue.title)) return false;
286	    if (stale.has(issue.number)) return false;
287	    if (!readyLabelOn(issue)) return false;
288	    const names = labelNames(issue);
289	    if (names.includes(AGENT_RUNNING_LABEL) || names.includes(NEEDS_HUMAN_LABEL)) return false;
290	    if ((issue.comments ?? 0) > 0) return false;
291	    return nowMs - new Date(issue.created_at).getTime() > graceMs;
292	  });
293	}
