1	// The pre-agent preprocessing stage (agent-preprocessing DESIGN §3). The
2	// scheduler runs a task's declared `agent_preprocessing` command as a SUBPROCESS
3	// before any agent starts — deterministic code work, Action-side, over the one
4	// sanctioned non-MCP surface (the Action GITHUB_TOKEN, inherited in `env`).
5	//
6	// The subprocess is the scheduler's child, so its `agent_preprocessing_timeout`
7	// is a HARD kill: a manual timer SIGKILLs an overrun and the run is reported
8	// failed. Its cwd is the TASK directory, so a declared `node worker.mjs` resolves
9	// to the script beside task.mjs (the containment the contract enforces); the repo
10	// root and slot context are handed in via CLAUDINITE_* env so the worker can act
11	// on the whole repo. Nothing the subprocess prints is threaded into the agent —
12	// preprocessing communicates only through the repository (DESIGN §3).
13	//
14	// THE LOG IS NOT THAT CHANNEL. The child's output is ECHOED to the scheduler's own
15	// stdout/stderr as it arrives, so the Action log carries what the worker actually
16	// did. That is an observability decision, not a data channel: no agent reads the
17	// log, and §3's "communicate only through the repository" is untouched. It is echoed
18	// LIVE rather than dumped at exit for the case that needs it most — a worker SIGKILLed
19	// at its timeout, whose buffered output would otherwise die with it. Before this,
20	// a failed worker surfaced as a bare `preprocessing exited 1` plus a three-line
21	// stderr tail in an issue, and diagnosing one meant reproducing it by hand.
22	
23	import { spawn } from 'node:child_process';
24	import { existsSync, rmSync, readFileSync } from 'node:fs';
25	import { join } from 'node:path';
26	import { tmpdir } from 'node:os';
27	
28	// Run `command` as a subprocess bounded by `timeoutSeconds`. Resolves (never
29	// rejects) with { ok, timedOut, code, signal, stdout, stderr }: `ok` is a clean
30	// zero exit that did not time out. `taskDir` is the cwd; `env` is the full
31	// environment the child inherits (the caller injects GITHUB_TOKEN + CLAUDINITE_*).
32	// `echo` (default on) mirrors the child's output to this process as it arrives —
33	// injected rather than hardcoded so a test can capture it instead of polluting the
34	// test runner's own output.
35	export function runPreprocessing(command, {
36	  taskDir, env, timeoutSeconds,
37	  echo = (chunk, stream) => (stream === 'stderr' ? process.stderr : process.stdout).write(chunk),
38	}) {
39	  return new Promise((resolve) => {
40	    const child = spawn(command, { cwd: taskDir, env, shell: true });
41	    let stdout = '';
42	    let stderr = '';
43	    let timedOut = false;
44	    // Echo is best-effort: a worker's output must never be the thing that fails the
45	    // run, so a broken sink is swallowed rather than propagated.
46	    const mirror = (chunk, stream) => { try { echo?.(String(chunk), stream); } catch { /* the run matters, the echo does not */ } };
47	    const timer = setTimeout(() => {
48	      timedOut = true;
49	      child.kill('SIGKILL'); // the hard kill — no grace period past the declared bound
50	    }, timeoutSeconds * 1000);
51	
52	    child.stdout?.on('data', (d) => { stdout += d; mirror(d, 'stdout'); });
53	    child.stderr?.on('data', (d) => { stderr += d; mirror(d, 'stderr'); });
54	    // A spawn error (command not found, etc.) is a failure, not a throw.
55	    child.on('error', (e) => {
56	      clearTimeout(timer);
57	      resolve({ ok: false, timedOut, code: null, signal: null, stdout, stderr: `${stderr}${e.message}` });
58	    });
59	    child.on('close', (code, signal) => {
60	      clearTimeout(timer);
61	      resolve({ ok: code === 0 && !timedOut, timedOut, code, signal, stdout, stderr });
62	    });
63	  });
64	}
65	
66	// The conditional-handoff signal (agent-preprocessing DESIGN §3, E4). A task with
67	// BOTH agent_preprocessing AND a non-`none` agent_model hands off to the agent
68	// ONLY when its worker requests it — so a task can absorb its work into
69	// preprocessing and be AGENTLESS on the quiet nights. The scheduler hands the
70	// worker this path via CLAUDINITE_REQUEST_AGENT and files `ready-for-agent` iff
71	// the worker created it. It is a pure control signal: the worker communicates
72	// DATA to the agent only through the repository, never through this file (DESIGN
73	// §3, "no code→agent data channel").
74	export function agentRequestPath({ pack, task, slotId }) {
75	  return join(tmpdir(), `claudinite-request-agent-${pack}-${task}-${slotId}`);
76	}
77	export function clearAgentRequest(path) { try { rmSync(path, { force: true }); } catch { /* nothing to clear */ } }
78	export function agentRequested(path) { return existsSync(path); }
79	
80	// …AND the artifacts that request refers to, plus why it was made. A worker writes
81	// JSON `{ delivered: { branch, pr, merged }, reason: { code, detail } }`, and the
82	// scheduler records both in the dispatch issue, which is where the agent reads them.
83	//
84	// This is the one thing that crosses the code→agent boundary as data (§3's named
85	// exception): identifiers for what this run created — a PR number, a branch ref — and
86	// the NAME of the condition that woke the agent. Never findings and never instructions:
87	// `reason.detail` says which gate fired and how many of what, and the findings
88	// themselves stay in the repo for the agent to re-run. Everything else still travels
89	// through the repository.
90	//
91	// Both keys are optional and their ABSENCE is meaningful, which is also what keeps an
92	// older vendored worker (one that predates a key) working: a worker that created
93	// nothing writes no `delivered` and the issue names none; a worker that does not know
94	// about `reason` writes none and the issue explains nothing, rather than asserting
95	// something false about why the agent is there.
96	export function readAgentRequest(path) {
97	  if (!existsSync(path)) return null;
98	  const raw = readFileSync(path, 'utf8').trim();
99	  if (!raw) return {};
100	  // A bare marker line (no payload) requests the agent and names no artifacts.
101	  try { return JSON.parse(raw); } catch { return {}; }
102	}
103	
104	// A one-line reason for the job summary / an issue comment when preprocessing
105	// fails — distinguishing a timeout kill from a non-zero exit.
106	export function preprocessingFailure(result) {
107	  if (result.timedOut) return 'preprocessing exceeded its agent_preprocessing_timeout and was killed';
108	  if (result.code !== null) return `preprocessing exited ${result.code}`;
109	  return `preprocessing could not run: ${result.stderr.trim().split('\n').pop() || 'unknown error'}`;
110	}
111

