// scheduler runs a task's declared `agent_preprocessing` command as a SUBPROCESS
// before any agent starts — deterministic code work, Action-side, over the one
// sanctioned non-MCP surface (the Action GITHUB_TOKEN, inherited in `env`).
//
// The subprocess is the scheduler's child, so its `agent_preprocessing_timeout`
// is a HARD kill: a manual timer SIGKILLs an overrun and the run is reported
// failed. Its cwd is the TASK directory, so a declared `node worker.mjs` resolves
// to the script beside task.mjs (the containment the contract enforces); the repo
// root and slot context are handed in via CLAUDINITE_* env so the worker can act
// on the whole repo. Nothing the subprocess prints is threaded into the agent —
// preprocessing communicates only through the repository (DESIGN §3).
//
// THE LOG IS NOT THAT CHANNEL. The child's output is ECHOED to the scheduler's own
// stdout/stderr as it arrives, so the Action log carries what the worker actually
// did. That is an observability decision, not a data channel: no agent reads the
// log, and §3's "communicate only through the repository" is untouched. It is echoed
// LIVE rather than dumped at exit for the case that needs it most — a worker SIGKILLed
// at its timeout, whose buffered output would otherwise die with it. Before this,
// a failed worker surfaced as a bare `preprocessing exited 1` plus a three-line
// stderr tail in an issue, and diagnosing one meant reproducing it by hand.

import { spawn } from 'node:child_process';
import { existsSync, rmSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

// Run `command` as a subprocess bounded by `timeoutSeconds`. Resolves (never
// rejects) with { ok, timedOut, code, signal, stdout, stderr }: `ok` is a clean
// zero exit that did not time out. `taskDir` is the cwd; `env` is the full
// environment the child inherits (the caller injects GITHUB_TOKEN + CLAUDINITE_*).
// `echo` (default on) mirrors the child's output to this process as it arrives —
// injected rather than hardcoded so a test can capture it instead of polluting the
// test runner's own output.
export function runPreprocessing(command, {
  taskDir, env, timeoutSeconds,
  echo = (chunk, stream) => (stream === 'stderr' ? process.stderr : process.stdout).write(chunk),
}) {
  return new Promise((resolve) => {
    const child = spawn(command, { cwd: taskDir, env, shell: true });
    let stdout = '';
    let stderr = '';
    let timedOut = false;
    // Echo is best-effort: a worker's output must never be the thing that fails the
    // run, so a broken sink is swallowed rather than propagated.
    const mirror = (chunk, stream) => { try { echo?.(String(chunk), stream); } catch { /* the run matters, the echo does not */ } };
    const timer = setTimeout(() => {
      timedOut = true;
      child.kill('SIGKILL'); // the hard kill — no grace period past the declared bound
    }, timeoutSeconds * 1000);

    child.stdout?.on('data', (d) => { stdout += d; mirror(d, 'stdout'); });
    child.stderr?.on('data', (d) => { stderr += d; mirror(d, 'stderr'); });
    // A spawn error (command not found, etc.) is a failure, not a throw.
    child.on('error', (e) => {
      clearTimeout(timer);
      resolve({ ok: false, timedOut, code: null, signal: null, stdout, stderr: `${stderr}${e.message}` });
    });
    child.on('close', (code, signal) => {
      clearTimeout(timer);
      resolve({ ok: code === 0 && !timedOut, timedOut, code, signal, stdout, stderr });
    });
  });
}

// The conditional-handoff signal (agent-preprocessing DESIGN §3, E4). A task with
// BOTH agent_preprocessing AND a non-`none` agent_model hands off to the agent
// ONLY when its worker requests it — so a task can absorb its work into
// preprocessing and be AGENTLESS on the quiet nights. The scheduler hands the
// worker this path via CLAUDINITE_REQUEST_AGENT and files `ready-for-agent` iff
// the worker created it. It is a pure control signal: the worker communicates
// DATA to the agent only through the repository, never through this file (DESIGN
// §3, "no code→agent data channel").
export function agentRequestPath({ pack, task, slotId }) {
  return join(tmpdir(), `claudinite-request-agent-${pack}-${task}-${slotId}`);
}
export function clearAgentRequest(path) { try { rmSync(path, { force: true }); } catch { /* nothing to clear */ } }
export function agentRequested(path) { return existsSync(path); }

// …AND the artifacts that request refers to, plus why it was made. A worker writes
// JSON `{ delivered: { branch, pr, merged }, reason: { code, detail } }`, and the
// scheduler records both in the dispatch issue, which is where the agent reads them.
//
// This is the one thing that crosses the code→agent boundary as data (§3's named
// exception): identifiers for what this run created — a PR number, a branch ref — and
// the NAME of the condition that woke the agent. Never findings and never instructions:
// `reason.detail` says which gate fired and how many of what, and the findings
// themselves stay in the repo for the agent to re-run. Everything else still travels
// through the repository.
//
// Both keys are optional and their ABSENCE is meaningful, which is also what keeps an
// older vendored worker (one that predates a key) working: a worker that created
// nothing writes no `delivered` and the issue names none; a worker that does not know
// about `reason` writes none and the issue explains nothing, rather than asserting
// something false about why the agent is there.
export function readAgentRequest(path) {
  if (!existsSync(path)) return null;
  const raw = readFileSync(path, 'utf8').trim();
  if (!raw) return {};
  // A bare marker line (no payload) requests the agent and names no artifacts.
  try { return JSON.parse(raw); } catch { return {}; }
}

// A one-line reason for the job summary / an issue comment when preprocessing
// fails — distinguishing a timeout kill from a non-zero exit.
export function preprocessingFailure(result) {
  if (result.timedOut) return 'preprocessing exceeded its agent_preprocessing_timeout and was killed';
  if (result.code !== null) return `preprocessing exited ${result.code}`;
  return `preprocessing could not run: ${result.stderr.trim().split('\n').pop() || 'unknown error'}`;
}

// What each scheduler run DID to each due task, as one machine-readable line per
// evaluation in the run's Actions log (skill-usage-metrics DESIGN §4.2).
//
// WHY A LINE AND NOT A FILE. The scheduler is stateless by design — its only
// watermark is the Actions run ledger — and a per-run write to a tracked branch
// would be 24 commits a day of data the run already emits. The Actions log is the
// record the run already leaves, is retained by the platform, and is readable over
// one API call; so the run states its outcomes there and whatever usage aggregation
// a repo declares reads them back. This module is the SINGLE source of truth for that
// format: the renderer the scheduler prints with and the parser a reader reads with
// sit next to each other, with a round-trip test pinning them together, because a
// format written in one place and re-guessed in another is exactly the drift this
// repo bans.
//
// WHY NOT THE HUMAN SUMMARY LINE (`renderSummary`). That line is written BEFORE the
// actions run and reports what was PLANNED — an agentful task whose preprocessing
// then requested no agent still reads as its dispatch decision there. These records
// are derived AFTER the loop, from the same record the loop mutated, so they report
// what actually happened. The human summary stays what it is: prose for a person
// reading the run.
//
// The counts these produce are exact within the Actions log retention window, and
// that is worth stating next to the capture-derived counts they land beside: every
// scheduler run logs every due task, so a task's invocation counts are a CENSUS of
// scheduled work — unlike the skill and check counts, which see only the sessions
// that captured.

// The five things a scheduler run can do with a due task. One name per outcome,
// used verbatim as the counter key in the aggregate, so there is no mapping table
// between "what the run said" and "what the fold counted" to drift.
export const TASK_RUN_OUTCOMES = Object.freeze([
  // A dispatch issue was filed: an executor session runs this task with an agent.
  'agent',
  // The task ran with NO agent — an `agent_model: none` task (preprocessing is the
  // whole task), or an agentful one whose preprocessing requested no agent stage.
  'preprocess',
  // Due, but its precondition said there was nothing to do.
  'skipped',
  // Its preprocessing failed; the run converged the task to a needs-human issue.
  'failed',
  // Due and past its precondition, but no NEW agent run started: this slot was
  // already dispatched (exactly-once), an earlier dispatch is still open
  // (at-most-one-open), or another task claimed the run exclusively. Work that
  // was wanted and did not happen this run.
  'deferred',
]);

// An empty per-task counter row — every outcome present, zeros included, so a row's
// shape never depends on which outcomes a task happened to hit.
export const emptyTaskRun = () => Object.fromEntries(TASK_RUN_OUTCOMES.map((o) => [o, 0]));

// What this run did to one evaluated task, from the record the action loop left
// behind (`planRun`'s evaluation, mutated in `main`). Pure — every field it reads
// is already on the record.
export function taskRunOutcome(rec) {
  if (!rec.run) return 'skipped';
  // Another task claimed the run exclusively (planRun). Its precondition DID ask
  // for work, so this is not a skip — it is the deferred kind: wanted, not done.
  // Stated ahead of the shape checks below because a deferred record carries none
  // of the flags they read, and "no dispatch" would otherwise have to mean this by
  // accident rather than on purpose.
  if (rec.deferred) return 'deferred';
  if (rec.preprocessResult && !rec.preprocessResult.ok) return 'failed';
  if (rec.inline) return 'preprocess';
  // Agentful. With preprocessing, the agent stage is CONDITIONAL: a task that
  // absorbed its work into the deterministic pass stays quiet, and that is a run of
  // the task, not a skip of it.
  if (rec.preprocessing && !rec.agentRequested) return 'preprocess';
  return rec.dispatch?.action === 'create' ? 'agent' : 'deferred';
}

// The line format. `v1` is the shape's version: a reader that meets a `v2` line
// knows it is looking at something it was not written for, instead of silently
// half-parsing it.
export const TASK_RUN_TAG = 'claudinite-task-run';
const VERSION = 'v1';

export const renderTaskRun = (rec) =>
  `${TASK_RUN_TAG} ${VERSION} ${rec.pack}/${rec.task} [${rec.slotId}] ${taskRunOutcome(rec)}`;

export const renderTaskRuns = (evaluations) => evaluations.map(renderTaskRun).join('\n');

// Actions stamps every log line with its own timestamp before the command's output,
// so the parse tolerates that prefix — without it, a fetched log reads as having
// printed nothing at all.
const LINE_RE = new RegExp(
  String.raw`^(?:\S+\s+)?${TASK_RUN_TAG} ${VERSION} (\S+)/(\S+) \[(\S+)\] ([a-z-]+)\s*$`,
);

// One line → `{ pack, task, slotId, outcome }`, or null for anything that is not a
// record of this version. Deliberately strict: an unknown outcome word is NOT a
// record, because counting it would mint a counter key nothing ever reads.
export function parseTaskRun(line) {
  const m = LINE_RE.exec(line);
  if (!m) return null;
  const [, pack, task, slotId, outcome] = m;
  if (!TASK_RUN_OUTCOMES.includes(outcome)) return null;
  return { pack, task, slotId, outcome };
}

// Every record in one job log. The log is the whole job's output — this picks its
// own lines out of it and ignores everything else.
export function parseTaskRuns(text) {
  const out = [];
  for (const line of String(text ?? '').split('\n')) {
    const rec = parseTaskRun(line);
    if (rec) out.push(rec);
  }
  return out;
}

