707:       + ' — closing it instead; the converge is idempotent and this cycle re-cuts it');
708:   }
709: 
710:   // Closed, not left to rot: whatever went wrong on that head, the next converge
711:   // reproduces the same content from the same inputs. Named in the log because a
712:   // member closing its maintenance PR every single night is a repo whose CI needs
713:   // a human, and the pattern has to be visible to be noticed.
714:   const closed = await gh(token, `/repos/${repo}/pulls/${pr.number}`, { method: 'PATCH', body: { state: 'closed' } });
715:   if (closed.status !== 200) {
716:     console.log(`baselining: could not close PR #${pr.number} (${closed.status}) — leaving it and skipping this cycle`);
717:     return pr;
718:   }
719:   console.log(`baselining: closed PR #${pr.number} — it did not land (${failureSummary(runs)}); re-cutting this cycle`);
720:   await deleteBranch(token, repo, pr.head?.ref);
721:   return null;
722: }
723: 
724: // Tidy the ref behind a disposed PR — a closed branch left on the remote is litter
725: // that accumulates one per cycle. Never fatal: the branch is not the deliverable.
726: async function deleteBranch(token, repo, ref) {
727:   if (!ref) return;
728:   const res = await gh(token, `/repos/${repo}/git/refs/heads/${encodeURIComponent(ref)}`, { method: 'DELETE' });
729:   if (res.status !== 204) console.log(`baselining: could not delete branch ${ref} (HTTP ${res.status})`);
730: }

805:   const json = await res.json().catch(() => null);
806:   if (json?.errors?.length) throw new Error(json.errors[0].message);
807: }
