809: export async function main() {
810:   const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
811:   const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
812:   const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
813:   const token = process.env.GITHUB_TOKEN;
814:   const requestFile = process.env.CLAUDINITE_REQUEST_AGENT;
815:   // Set by deliver() to `{ branch, pr, merged }`; stays null when this cycle opened
816:   // nothing, which is what the dispatch issue then says.
817:   let delivered = null;
818:   if (!repo) { console.error('baselining: no repo (CLAUDINITE_REPO/GITHUB_REPOSITORY)'); process.exit(1); }
819:   if (!token) { console.error('baselining: no GITHUB_TOKEN in env'); process.exit(1); }
820: 
821:   const checksPath = join(root, '.claudinite-checks.json');
822:   if (!existsSync(checksPath)) { console.log('baselining: no .claudinite-checks.json — nothing to self-refresh'); return; }
823:   const priorRaw = JSON.parse(readFileSync(checksPath, 'utf8'));
824:   const priorStamp = priorRaw.claudinite ?? {};
825:   if (!priorStamp.updated && !priorStamp.ref) {
826:     console.log('baselining: no vendored-mount stamp — nothing to self-refresh (canon home or pre-adoption)');
827:     return; // quiet, no agent (matches the precondition self-skip)
828:   }
829:   const { delivery, materialize } = resolveDelivery(priorRaw?.maintenance?.delivery);
830:   if (!delivery) {
831:     console.error(`baselining: maintenance.delivery "${priorRaw?.maintenance?.delivery}" is neither auto-merge nor review`);
832:     process.exit(1);
833:   }
834:   // Materialize the missing key BEFORE the converge, so the repair rides this
835:   // cycle's maintenance commit like any other converged surface.
836:   if (materialize) {
837:     priorRaw.maintenance = { ...priorRaw.maintenance, delivery };
838:     writeFileSync(checksPath, JSON.stringify(priorRaw, null, 2) + '\n');
839:     console.log(`baselining: maintenance.delivery was missing — materialized "${delivery}"`);
840:   }
841: 
842:   // 1. Fetch canon at head as a ROOTLESS tree (drop .git so apply-vendor-set's
843:   //    ancestry guards skip — a shallow clone can't answer them, and it is head
844:   //    by construction).
845:   const source = canonSource(process.env);
846:   const tmp = mkdtempSync(join(tmpdir(), 'claudinite-canon-'));
847:   git(source.ref
848:     ? ['clone', '--depth', '1', '--branch', source.ref, source.url, tmp]
849:     : ['clone', '--depth', '1', source.url, tmp]);
850:   const headSha = git(['-C', tmp, 'rev-parse', 'HEAD']).trim();
851:   rmSync(join(tmp, '.git'), { recursive: true, force: true });
852:   if (source.rehearsal) {
853:     console.log(`baselining: REHEARSAL against ${source.url}@${source.ref} (${headSha.slice(0, 8)}) — `
854:       + 'the stamp will be restored, and nothing is delivered');
855:   }
856: 
857:   // 2-4. Deterministic converge: mount + stamp, then wiring, then mechanical notes.
858:   node([join(tmp, 'vendoring/apply-vendor-set.mjs'), '--target', root, '--ref', headSha]);
859:   const wiringOut = node([join(tmp, 'engine/scheduler/converge-wiring.mjs'), repo], { CLAUDINITE_REPO_ROOT: root });
860:   // The handshake (migrations/registry.mjs, WITHHOLD_CAPABLE_ENV): THIS worker withholds
861:   // workflow paths from its commit and hands them to the agent, so a record may safely
862:   // materialize one. An older vendored worker does not set it and the materialization is
863:   // skipped instead of wedging its push. Set here, by the code that does the withholding,
864:   // because the question is what the RUNNING process can do — and the disk cannot answer
865:   // it: apply-vendor-set above has already overwritten this very file with the new
866:   // version while this old-or-new code is the thing actually executing.
867:   node([join(tmp, 'migrations/apply.mjs')], { CLAUDE_PROJECT_DIR: root, CLAUDINITE_CAN_WITHHOLD_WORKFLOWS: '1' });
868: 
869:   // Ask about any declared secret the repo hasn't configured — but only once the
870:   // wiring is settled. On the cycle that FIRST stamps a name into the workflow the
871:   // value cannot be in this process's env yet, so asking then would nag about a
872:   // secret the owner may well have already added; next cycle tells the truth.
873:   const { declaredSecrets } = await import(pathToFileURL(join(tmp, 'engine/scheduler/converge-wiring.mjs')).href);
874:   const missingSecrets = wiringOut.includes('.github/workflows/claudinite-scheduler.yml')
875:     ? []
876:     : unconfiguredSecrets(await declaredSecrets(root, JSON.parse(readFileSync(checksPath, 'utf8'))), process.env);
877:   if (missingSecrets.length && await askForSecrets(token, repo, missingSecrets)) {
878:     console.log(`baselining: asked the owner to configure ${missingSecrets.join(', ')}`);
879:   }
880: 
881:   // 5. Pending agentic notes (from the fresh canon clone) + stamp hold.
882:   const { loadMigrations, agenticMigrations } = await import(pathToFileURL(join(tmp, 'migrations/registry.mjs')).href);
883:   const pending = pendingAgentic(agenticMigrations(await loadMigrations()), priorStamp.updated);
884:   if (pending.length) {
885:     const raw = JSON.parse(readFileSync(checksPath, 'utf8'));
886:     raw.claudinite = { ...raw.claudinite, updated: heldStamp(pending) };
887:     writeFileSync(checksPath, JSON.stringify(raw, null, 2) + '\n');
888:   }
889: 
890:   // 6. Meaningful change? A stamp-only bump against an unchanged head is not one —
891:   //    revert it and stay quiet (no nightly stamp-only noise).
892:   const changed = git(['-C', root, 'status', '--porcelain'])
893:     .split('\n').map((l) => l.slice(3)).filter(Boolean);
894:   // `materialize` excluded: a materialized delivery key also touches only
895:   // .claudinite-checks.json, and reverting it would re-drift the repo every night
896:   // and never land the repair.
897:   const onlyStamp = changed.length > 0 && !materialize && changed.every((p) => p === '.claudinite-checks.json');
898:   if (onlyStamp && priorStamp.ref === headSha && !pending.length) {
899:     git(['-C', root, 'checkout', '--', '.claudinite-checks.json']);
900:     console.log('baselining: mount already at canon head, nothing changed — agentless, quiet');
901:     return;
902:   }
903:   const meaningfulChange = changed.length > 0;
904:   // What this stage cannot push. Computed here, before the escalation gate, because a
905:   // withheld file is residual work for the agent exactly like a pending agentic note.
906:   const withheld = withheldWorkflowPaths(changed);
907:   if (withheld.length) {
908:     console.log(`baselining: withholding ${withheld.length} workflow file(s) from the push — `
909:       + `the Action token cannot write .github/workflows/; the agent stage lands them: ${withheld.join(', ')}`);
910:   }
911: 
912:   // 6b. SELF-TEST the converged tree before judging its content. This asks "can
913:   //     Claudinite still run here?" — mount, stamp, pack manifests, hook targets,
914:   //     mounted skills, cron, migrations registry — and it is the gate that would
915:   //     have caught #555 the night it landed: a required manifest field arrived
916:   //     with no migration, every consumer pack stopped validating, and because a
917:   //     pack that fails validation contributes NO rules, check_the_world went on
918:   //     reporting green about a corpus it was no longer running. A content check
919:   //     cannot see its own machinery break. This runs on the just-converged tree,
920:   //     so it judges what the member is about to live with.
921:   const selftest = runSelfTest(root);
922:   if (!selftest.ok) {
923:     console.log('baselining: the converged mount FAILED its self-test — requesting the agent');
924:     logGateOutput('selftest --strict', selftest);
925:   }
926: 
927:   // 7. Escalation gate: run the conformance checks only when a change happened and
928:   //    no agentic note already forces the agent. A failed self-test forces it too:
929:   //    broken machinery is exactly the judgment case, and merging it would spread
930:   //    the breakage to a repo that was working an hour ago.
931:   const checks = (meaningfulChange && !pending.length) ? runCheckTheWorld(root) : GATE_ABSENT;
932:   if (!checks.ok) logGateOutput('check_the_world', checks);
933:   const reason = escalation({
934:     pendingCount: pending.length, meaningfulChange, checksPass: checks.ok, selftestOk: selftest.ok,
935:     withheldCount: withheld.length, checksCrashed: checks.crashed, selftestCrashed: selftest.crashed,
936:   });
937:   const requestAgent = reason !== null;
938: 
939:   // 7b. A REHEARSAL stops here. It has done the only thing it was for — converged
940:   //     this real repo against a canon BRANCH and asked whether the result still
941:   //     works — and now it must leave no trace: no commit, no branch, no PR, and
942:   //     above all no stamp. Stamping a branch head would leave the member
943:   //     `ref-not-on-trunk`, which the #328 anti-rewind guard then refuses to
944:   //     converge over: a rehearsal that wedged the repo it was rehearsing on.
945:   //     `git checkout -- .` restores the working tree wholesale, so the mount goes
946:   //     back to the vendored snapshot the repo actually runs.
947:   if (source.rehearsal) {
948:     git(['-C', root, 'checkout', '--', '.']);
949:     const verdict = selftest.ok && checks.ok ? 'PASS' : 'FAIL';
950:     console.log(`baselining: rehearsal ${verdict} — selftest ${selftest.ok ? 'ok' : 'FAILED'}, `
951:       + `checks ${checks.ok ? 'green' : 'RED'}, ${changed.length} file(s) would have changed. Working tree restored.`);
952:     if (verdict === 'FAIL') process.exit(1);   // the canary's whole purpose: fail the canon PR
953:     return;
954:   }
955: 
956:   // 8. Deliver the converge (only when there's something to land).
957:   if (meaningfulChange || pending.length) {
958:     const seed = Math.random().toString(36).slice(2, 8);
959:     delivered = await deliver(root, repo, base, token, delivery, seed, withheld);
960:     console.log(`baselining: delivered converge on ${delivered.branch}${delivered.pr ? ` (PR #${delivered.pr}${delivered.merged ? ', merged' : ''})` : ''} (${delivery})`);
961:   } else {
962:     console.log('baselining: no change to deliver');
963:   }
964: 
965:   // 9. Request the agent only when judgment is left (conditional handoff, §3) — naming
966:   //    what this run created AND why the agent is being woken. `delivered` stays null
967:   //    when nothing was opened, and the issue then names nothing; `reason` is non-null
968:   //    exactly when the agent is requested at all.
969:   if (requestAgent && requestFile) {
970:     writeFileSync(requestFile, `${JSON.stringify({ marker: AGENT_REQUEST_MARKER, delivered, reason })}\n`);
971:   }
972:   console.log(requestAgent
973:     ? `baselining: requested agent stage (${reason.code}: ${reason.detail})`
974:     : 'baselining: agentless night — deterministic converge delivered, no agent needed');
975: }
976: 
977: // Run only when invoked directly (the scheduler's `node worker.mjs`), never on
978: // import — a test imports the pure helpers without any git or network.
979: if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
980:   main().catch((e) => { console.error(`baselining preprocessing failed: ${e.message}`); process.exit(1); });

