373	export function countEntries(entries, mounted = new Set()) {
374	  const skillLoads = {};
375	  let userMessages = 0;
376	  let userCommands = 0;
377	  const load = (name) => { skillLoads[name] = (skillLoads[name] ?? 0) + 1; };
378	
379	  for (const entry of entries) {
380	    for (const name of skillToolLoads(entry)) load(name);
381	    if (isUserMessage(entry)) userMessages += 1;
382	    const command = commandName(entry);
383	    if (command !== null) {
384	      userCommands += 1;
385	      if (mounted.has(command)) load(command);
386	    }
387	  }
388	  return { userMessages, userCommands, skillLoads, ...countChecks(entries) };
389	}
390	
391	// --- day buckets ---------------------------------------------------------------
392	
393	// An empty day row — the shape every counter folds through.
394	const emptyDay = () => ({
395	  captures: 0, merges: 0, sessions: 0, userMessages: 0, userCommands: 0, skillLoads: {},
396	  checks: {}, checkFindings: {}, tasks: {},
397	});
398	
399	function addLoads(into, from) {
400	  for (const [name, n] of Object.entries(from)) into[name] = (into[name] ?? 0) + n;
401	}
402	
403	// The check maps fold the same way skillLoads do — key-wise, zeros implicit — only
404	// with a fixed-shape counter object under each key instead of a bare number.
405	function addCounters(into, from) {
406	  for (const [key, row] of Object.entries(from ?? {})) {
407	    const target = (into[key] ??= Object.fromEntries(Object.keys(row).map((k) => [k, 0])));
408	    for (const [field, n] of Object.entries(row)) target[field] = (target[field] ?? 0) + n;
409	  }
410	}
411	
412	// Recompute the day rows from scratch, from the live capture files. `files` is
413	// `[{ date, issue, sessionId, counts }]` — one entry per capture file in the raw
414	// window, `counts` being that file's `countEntries` result.
415	//
416	// Stateless by construction: a day is a pure function of the files stamped with it,
417	// so there is no ingest ledger, no double-count risk, and a counting-bug fix
418	// self-heals the entire visible window on its next run.
419	export function foldDays(files) {
420	  const days = {};
421	  const sessionsByDay = {};
422	  for (const file of files) {
423	    const day = (days[file.date] ??= emptyDay());
424	    day.captures += 1;
425	    if (file.issue > 0) day.merges += 1;      // issue 0 = a capture with no merge behind it
426	    day.userMessages += file.counts.userMessages;
427	    day.userCommands += file.counts.userCommands;
428	    addLoads(day.skillLoads, file.counts.skillLoads);
429	    addCounters(day.checks, file.counts.checks);
430	    addCounters(day.checkFindings, file.counts.checkFindings);
431	    (sessionsByDay[file.date] ??= new Set()).add(file.sessionId);
432	  }
433	  // Distinct sessions, not capture count: one session can capture more than once
434	  // (a merge, then the session-end tail).
435	  for (const [date, set] of Object.entries(sessionsByDay)) days[date].sessions = set.size;
436	  return days;
437	}
438	
439	// --- task invocations -----------------------------------------------------------
440	
441	// How long a task row stays in the DAY tier. Independent of the capture retention
442	// on purpose: these rows come from the scheduler's Actions logs, not from the logs
443	// branch, so nothing about them ages out when a capture file does — and a repo that
444	// captured nothing for a week must still show that its scheduled tasks ran. Past
445	// this, the day row goes and its week row carries it, exactly as the capture-derived
446	// days do.
447	export const TASK_DAY_WINDOW_DAYS = 14;
448	
449	export function withinTaskWindow(date, today, days = TASK_DAY_WINDOW_DAYS) {
450	  const age = (new Date(`${today}T00:00:00Z`) - new Date(`${date}T00:00:00Z`)) / 86400000;
451	  return Number.isFinite(age) && age >= 0 && age < days;
452	}
453	
454	// Accumulate this run's new task-run records into the day rows, on top of what
455	// earlier folds already counted.
456	//
457	// APPEND-ONCE, not recomputed — the one place this file departs from "days are a
458	// pure function of their sources", and deliberately. The capture files are a local
459	// git branch this fold can re-read for free; the scheduler's run logs are a paged
460	// REST resource with a rate budget, and re-reading the whole window every night
461	// would cost ~20x the API calls for an identical answer. So the caller reads only
462	// the runs past the `runsFoldedThrough` watermark and hands them here, and the
463	// watermark is the entire exactly-once mechanism — the same trade the week rows
464	// already make, with the same consequence stated in the same place: a counting bug
465	// fixed later does NOT heal these rows, it applies from the fix forward.
466	//
467	// `records` is `[{ date, pack, task, outcome }]`; `priorDays` is the previous file's
468	// day rows, whose task counts are carried forward while they are inside the window.
469	export function foldTaskRuns(days, priorDays = {}, records = [], today) {
470	  for (const [date, row] of Object.entries(priorDays)) {
471	    const tasks = row?.tasks;
472	    if (!tasks || !Object.keys(tasks).length || !withinTaskWindow(date, today)) continue;
473	    (days[date] ??= emptyDay()).tasks = structuredClone(tasks);
474	  }
475	  for (const { date, pack, task, outcome } of records) {
476	    if (!TASK_RUN_OUTCOMES.includes(outcome)) continue;   // an outcome word this fold does not know
477	    const day = (days[date] ??= emptyDay());
478	    const row = (day.tasks[`${pack}/${task}`] ??= emptyTaskRun());
479	    row[outcome] += 1;
480	  }
481	  return days;
482	}
483	
484	// --- week buckets --------------------------------------------------------------
485	
486	// The ISO-8601 week a UTC date falls in, `YYYY-Www`. ISO weeks start Monday and
487	// belong to the year containing their Thursday — computed, never approximated,
488	// because an off-by-one here would silently mis-file a whole week's row.
489	export function isoWeek(date) {
490	  const d = new Date(`${date}T00:00:00Z`);
491	  const day = (d.getUTCDay() + 6) % 7;                 // Mon=0 … Sun=6
492	  d.setUTCDate(d.getUTCDate() - day + 3);              // the week's Thursday
493	  const year = d.getUTCFullYear();
494	  const firstThursday = new Date(Date.UTC(year, 0, 4));
495	  const offset = (firstThursday.getUTCDay() + 6) % 7;
496	  firstThursday.setUTCDate(firstThursday.getUTCDate() - offset + 3);
497	  const week = 1 + Math.round((d - firstThursday) / (7 * 86400000));
498	  return `${year}-W${String(week).padStart(2, '0')}`;
499	}
500	
501	// The days to fold into weeks this run: every completed day strictly after the
502	// watermark and strictly before today, in order. Days close strictly in order, so a
503	// single monotone watermark is the WHOLE exactly-once mechanism — no ingest ledger.
504	// `today` is excluded because its capture files are still arriving.
505	export function daysToFold(days, foldedThrough, today) {
506	  return Object.keys(days)
507	    .filter((d) => d < today && (!foldedThrough || d > foldedThrough))
508	    .sort();
509	}
510	
511	// Add one day row into its week row, append-once. Weeks carry `days` — how many day
512	// rows they absorbed — so a fold outage longer than the raw retention window
513	// declares its own hole (`days: 5`) instead of silently under-reporting.
514	//
515	// `sessionDays` rather than `sessions`: every counter here sums exactly under
516	// folding EXCEPT a distinct-session count (a session spanning two days is distinct
517	// in each), so the week-level field is named for what it actually is — the sum of
518	// the day-level distinct counts — rather than claiming a precision folding cannot
519	// give.
520	export function addDayToWeek(week, day) {
521	  const w = week ?? {
522	    days: 0, captures: 0, merges: 0, sessionDays: 0, userMessages: 0, userCommands: 0,
523	    skillLoads: {}, checks: {}, checkFindings: {},
524	  };
525	  w.days += 1;
526	  w.captures += day.captures;
527	  w.merges += day.merges;
528	  w.sessionDays += day.sessions;
529	  w.userMessages += day.userMessages;
530	  w.userCommands += day.userCommands;
531	  addLoads(w.skillLoads, day.skillLoads);
532	  // A week folded before the checks were counted has no `checks` key at all —
533	  // default rather than crash, so the first fold after this shipped extends the
534	  // existing weeks instead of refusing to advance the watermark past them.
535	  addCounters((w.checks ??= {}), day.checks);
536	  addCounters((w.checkFindings ??= {}), day.checkFindings);
537	  // Same default-rather-than-crash treatment for the task invocations: a week
538	  // folded before they were counted has no `tasks` key, and grows one from the day
539	  // it closes forward instead of wedging the watermark behind it.
540	  addCounters((w.tasks ??= {}), day.tasks);
541	  return w;
542	}
543	
544	// --- the whole file ------------------------------------------------------------
545	
546	export const USAGE_VERSION = 1;
547	
548	// Sorted keys throughout, so a recompute that found nothing new produces a
549	// byte-identical file and the delivery opens no PR.
550	function sortKeys(obj) {
551	  return Object.fromEntries(Object.keys(obj).sort().map((k) => [k, obj[k]]));
552	}
553	
554	function sortRow(row) {
555	  return {
556	    ...row,
557	    skillLoads: sortKeys(row.skillLoads),
