attachment.snippet:
1	// Executor-side deterministic validation of a dispatch issue, BEFORE any model
2	// judgment (per-project-scheduling DESIGN §5.2). Given the issue body, it asserts
3	// in code that the first line is a legal task path, the task file exists at HEAD,
4	// its pack is declared, and its `task.mjs` sibling parses to a well-formed
5	// declaration — then resolves the model and outcome ceiling the executor will
6	// enforce. An invalid dispatch is rejected (the executor de-labels it and
7	// converges it to needs-human), so a forged or mangled issue never runs.
8	//
9	// Pure over injected capabilities so it unit-tests without a repo or GitHub. It
10	// is NOT a CLI — the executor shell beside it, `resolve-dispatch.mjs`, is what
11	// drives it in production: that shell takes the issue body out of the label
12	// event's payload on disk and wires `exists`/`isPackDeclared`/`loadTask` to the
13	// checkout, so validating a dispatch costs no GitHub call at all.
14	
15	import { normalizeTaskDeclaration, validateTaskDeclaration } from './task-contract.mjs';
16	import { resolveModel } from './model-map.mjs';
17	
18	// The only shape a dispatch first line may take (DESIGN §5.2). Anchored end to
19	// end — no query strings, no trailing junk, exactly one pack and one task
20	// segment under a packs/ root. The `.claudinite/(shared|local)/` prefix is
21	// OPTIONAL: a consumer's task path carries it (its canon is mounted at
22	// `.claudinite/shared/packs/`, its own packs at `.claudinite/local/packs/`),
23	// while the CANON repo runs its own tree and dispatches root-relative paths
24	// (`packs/<pack>/…` for its canon packs, `.claudinite/local/packs/<pack>/…` for
25	// its local packs). All three forms are legal; nothing else is.
26	export const DISPATCH_PATH_RE = /^(?:\.claudinite\/(?:shared|local)\/)?packs\/([^/]+)\/tasks\/([^/]+)\/task\.md$/;
27	
28	// The task path a dispatch body points at — its first line, trimmed.
29	export const dispatchFirstLine = (body) => String(body ?? '').split('\n')[0].trim();
30	
31	const reject = (reason, extra = {}) => ({ ok: false, reason, ...extra });
32	
33	// Validate a dispatch body. Capabilities (all injected for testability):
34	//   exists(path)        -> boolean   — does this repo-relative path exist at HEAD
35	//   isPackDeclared(id)  -> boolean   — is this pack active in .claudinite-checks.json
36	//   loadTask(mjsPath)   -> decl      — load the task.mjs default export (throws on parse error)
37	// Returns { ok:true, pack, task, taskPath, model, resolvedModel, outcome },
38	// { ok:false, gone:true, pack, task, reason } — a well-formed dispatch whose task
39	// the repo NO LONGER CARRIES (file gone, sibling gone, pack undeclared): the
40	// executor CLOSES the issue as obsolete (owner, 2026-08-06) rather than parking
41	// it on needs-human, because a task that was removed or deactivated is not an
42	// anomaly a human needs to triage — or { ok:false, reason } for a genuinely
43	// malformed dispatch (bad path shape, unparseable declaration), which stays a
44	// needs-human convergence since it may be forgery or a broken task.
45	export function validateDispatchBody(body, { exists, isPackDeclared, loadTask }) {
46	  const firstLine = dispatchFirstLine(body);
47	  const m = DISPATCH_PATH_RE.exec(firstLine);
48	  if (!m) return reject(`first line "${firstLine}" is not a valid task path (${DISPATCH_PATH_RE})`);
49	
50	  const [, pack, task] = m;
51	  const taskPath = firstLine;
52	  const mjsPath = taskPath.replace(/task\.md$/, 'task.mjs');
53	
54	  const gone = (reason) => reject(reason, { gone: true, pack, task });
55	  if (!exists(taskPath)) return gone(`task file ${taskPath} does not exist at HEAD — the repo no longer carries this task`);
56	  if (!exists(mjsPath)) return gone(`the task.mjs sibling ${mjsPath} is missing — the repo no longer carries this task`);
57	  if (!isPackDeclared(pack)) return gone(`pack "${pack}" is not declared in .claudinite-checks.json — this task is not active here`);
58	
59	  let decl;
60	  try {
61	    decl = normalizeTaskDeclaration(loadTask(mjsPath));
62	  } catch (e) {
63	    return reject(`${mjsPath} did not parse: ${e.message}`, { pack, task });
64	  }
65	  const problems = validateTaskDeclaration(decl);
66	  if (problems.length) return reject(`${mjsPath} is not a valid task declaration: ${problems.map((p) => p.what).join('; ')}`, { pack, task });
67	
68	  return {
69	    ok: true,
70	    pack,
71	    task,
72	    taskPath,
73	    model: decl.agent_model,
74	    resolvedModel: resolveModel(decl.agent_model),
75	    outcome: decl.expected_outcome,
76	    // The best-effort run bound (task-prework DESIGN §6): the executor
77	    // surfaces it into the subagent's brief as "fail after N minutes". Always set
78	    // for an agentic task (the contract requires it); null for an agentless one.
79	    executionTimeout: decl.agent_execution_timeout ?? null,
80	  };
81	}

