  id: ${JSON.stringify(id)},
  frequency: 'daily',
  precondition_signals: ['commits'],
  agent_model: 'sonnet',
  expected_outcome: 'open-pr',
  agent_instructions: 'task.md',
  agent_execution_timeout: 1800,
  precondition: () => ({ run: true, reason: 'due' }),
};
`;

