30	  // this run chose not to do it. Counting it as a skip would make a repo whose
31	  // nightly chain is repeatedly held back look exactly like one with nothing to do.
32	  assert.equal(taskRunOutcome(rec({ deferred: 'deferred — basics/baselining claimed this run exclusively' })), 'deferred');
33	  // Deferral is decided before prework, so the flag can ride a record that
